1	/**
2	 * @module features/tv-dashboard/ui/TvDashboard.page
3	 *
4	 * Página `/tv` — Dashboard de Crise (design.md §1–§2, §7–§8). Renderiza
5	 * FORA do DashboardLayout (sem sidebar), em LIGHT hardcoded (independe do
6	 * toggle de tema): glassmorphism Momma sobre fundo branco com ambiência da
7	 * marca (awning, folhas, glows). Layout FLUIDO mobile-first: empilha com
8	 * scroll natural em telas pequenas e trava na viewport (zero scroll) em
9	 * TV/monitor grande via `.tv-lock-*` (tv.css).
10	 */
11	
12	import { useEffect, useRef, useState } from 'react';
13	import { useNavigate } from 'react-router-dom';
14	import { Leaf, Settings2 } from 'lucide-react';
15	import { useTvDashboardData } from '../model/useTvDashboardData';
16	import { useTvRealtime } from '../model/useTvRealtime';
17	import { TvHero } from './TvHero';
18	import { TvStoreCard } from './TvStoreCard';
19	import { TvFabricaCard } from './TvFabricaCard';
20	import { TvExceptions } from './TvExceptions';
21	import { TvTopProducts } from './TvTopProducts';
22	import { useMinuteClock } from '../model/useMinuteClock';
23	import './tv.css';
24	
25	/** Tempo que o botão Metas permanece visível após mousemove (§8.4). */
26	const METAS_BUTTON_VISIBLE_MS = 5_000;
27	
28	/**
29	 * Ambiência Momma replicada do `MommaPageLayout` (que não cabe no chassi
30	 * fullscreen da TV): awning stripe verde no topo, folhas decorativas
31	 * ESTÁTICAS (sem `animate-pulse` — §8.2 proíbe animação contínua) e
32	 * ambient glows verde/dourado.
33	 */
34	function TvAmbience() {
35	  return (
36	    <div className="pointer-events-none absolute inset-0 overflow-hidden" aria-hidden>
37	      {/* Awning stripe (toldo da marca) */}
38	      <div className="absolute left-0 right-0 top-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80" />
39	      {/* Folhas decorativas estáticas */}
40	      <div className="absolute right-[-10%] top-[-5%] h-[300px] w-[300px] opacity-[0.03]">
41	        <Leaf className="h-full w-full rotate-12 text-[#57715B]" />
42	      </div>
43	      <div className="absolute bottom-[-10%] left-[-15%] h-[400px] w-[400px] opacity-[0.03]">
44	        <Leaf className="h-full w-full -rotate-45 text-[#57715B]" />
45	      </div>
46	      {/* Ambient glows */}
47	      <div className="absolute left-[10%] top-[20%] h-[200px] w-[200px] rounded-full bg-[#57715B]/5 blur-[80px]" />
48	      <div className="absolute bottom-[30%] right-[10%] h-[250px] w-[250px] rounded-full bg-[#C5A065]/5 blur-[80px]" />
49	    </div>
50	  );
51	}
52	
53	/** Card-chassi anônimo do estado de erro total (design.md §7). */
54	function TvErrorCard() {
55	  return (
56	    <section className="relative flex flex-col overflow-hidden rounded-[2rem] border border-[#57715B]/10 bg-white/60 p-4 shadow-[0_8px_32px_rgba(0,0,0,0.06)] backdrop-blur-xl saturate-150 lg:p-5">
57	      <div
58	        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
59	        aria-hidden
60	      />
61	      <div className="relative z-10 flex h-full flex-col">
62	        <div className="flex items-center justify-between gap-3">
63	          <span className="font-momma text-[clamp(1rem,1.45vw,2.625rem)] font-semibold text-[#7C887E]">
64	            —
65	          </span>
66	          <span className="inline-flex items-center rounded-full border border-amber-400/40 bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium text-amber-600">
67	            sem conexão
68	          </span>
69	        </div>
70	        <span className="mt-4 font-momma text-[clamp(2rem,3.35vw,6rem)] font-bold leading-none text-[#7C887E]">
71	          —
72	        </span>
73	      </div>
74	    </section>
75	  );
76	}
77	
78	/** Página raiz do painel TV. */
79	export default function TvDashboardPage() {
80	  const navigate = useNavigate();
81	  const data = useTvDashboardData();
82	  useTvRealtime();
83	  const now = useMinuteClock();
84	
85	  // Telas touch (sem hover) não disparam mousemove confiável — o botão
86	  // Metas fica SEMPRE visível, discreto no canto (design.md §8.4).
87	  const [isTouch] = useState(
88	    () =>
89	      typeof window !== 'undefined' &&
90	      typeof window.matchMedia === 'function' &&
91	      window.matchMedia('(hover: none)').matches,
92	  );
93	
94	  // Botão fantasma "Metas": invisível por padrão; mousemove revela por 5s
95	  // e suspende o cursor-none enquanto visível (design.md §8.4).
96	  const [controlsVisible, setControlsVisible] = useState(false);
97	  const hideTimer = useRef<number | null>(null);
98	  useEffect(() => {
99	    const onMove = () => {
100	      setControlsVisible(true);
101	      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
102	      hideTimer.current = window.setTimeout(
103	        () => setControlsVisible(false),
104	        METAS_BUTTON_VISIBLE_MS,
105	      );
106	    };
107	    window.addEventListener('mousemove', onMove);
108	    return () => {
109	      window.removeEventListener('mousemove', onMove);
110	      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
111	    };
112	  }, []);
113	
114	  // ── Loading inicial (§7): wordmark + frase + 3 pontos em sequência ──
115	  if (data.isLoading) {
116	    return (
117	      <div className="relative flex min-h-dvh select-none flex-col items-center justify-center gap-5 bg-white font-momma antialiased">
118	        <TvAmbience />
119	        <span className="relative text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold uppercase tracking-[0.3em] text-[#C5A065]">
120	          MOMMA
121	        </span>
122	        <span className="relative text-[clamp(1rem,1.25vw,2.25rem)] text-[#5F6F63]">
123	          carregando painel…
124	        </span>
125	        <div
126	          className="relative flex gap-2 text-[clamp(1rem,1.25vw,2.25rem)] text-[#7C887E]"
127	          aria-hidden
128	        >
129	          <span className="tv-dot">·</span>
130	          <span className="tv-dot">·</span>
131	          <span className="tv-dot">·</span>
132	        </div>
133	      </div>
134	    );
135	  }
136	
137	  const storeCards = data.stores.slice(0, data.factory ? 5 : 6);
138	
139	  // Em touch o botão Metas é permanente; com mouse, segue o ghost de 5s.
140	  const metasVisible = isTouch || controlsVisible;
141	
142	  return (
143	    <div
144	      className={`tv-lock-viewport relative min-h-dvh select-none overflow-x-hidden bg-white font-momma text-[#2D362E] antialiased ${
145	        metasVisible ? '' : 'cursor-none'
146	      }`}
147	      data-testid="tv-dashboard"
148	    >
149	      <TvAmbience />
150	
151	      <div className="tv-pixel-shift tv-lock-fill relative">
152	        <div className="tv-content-enter tv-lock-fill flex flex-col gap-4 p-4 sm:p-6 lg:gap-6 lg:px-8 lg:py-6">
153	          {/* Linha 1 — hero */}
154	          <TvHero network={data.network} freshness={data.freshness} now={now} />
155	
156	          {/* Linha 2 — grid de unidades (fábrica na posição 6): empilha no
157	              mobile, 2 colunas em sm+, 3 colunas em xl+; no viewport-lock
158	              absorve a altura restante (tv-lock-grow). */}
159	          <div className="tv-lock-grow grid auto-rows-fr grid-cols-1 gap-4 sm:grid-cols-2 lg:gap-6 xl:grid-cols-3">
160	            {data.isError ? (
161	              <>
162	                {Array.from({ length: 6 }, (_, i) => (
163	                  <TvErrorCard key={i} />
164	                ))}
165	              </>
166	            ) : (
167	              <>
168	                {storeCards.map((store) => (
169	                  <TvStoreCard
170	                    key={store.lojaId}
171	                    store={store}
172	                    liveLevel={data.freshness.vendasLive.level}
173	                    now={now}
174	                  />
175	                ))}
176	                {data.factory && (
177	                  <TvFabricaCard
178	                    factory={data.factory}
179	                    freshness={data.freshness}
180	                    now={now}
181	                  />
182	                )}
183	              </>
184	            )}
185	          </div>
186	
187	          {/* Linha 3 — exceções + top 5 produtos: empilham no mobile,
188	              2fr/1fr lado a lado em lg+ */}
189	          <div className="grid grid-cols-1 gap-4 lg:grid-cols-[2fr_1fr] lg:gap-6">
190	            <TvExceptions exceptions={data.exceptions} />
191	            <TvTopProducts products={data.topProducts} />
192	          </div>
193	        </div>
194	      </div>
195	
196	      {/* Botão de Metas (§8.4): fantasma com mouse, permanente em touch */}
197	      <button
198	        type="button"
199	        onClick={() => navigate('/tv/metas')}
200	        data-mia-action="abrir-metas-painel-tv"
201	        className={`fixed bottom-4 right-4 flex h-11 items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-5 font-momma text-[clamp(0.875rem,1.05vw,1.25rem)] font-medium text-[#57715B] shadow-[0_4px_16px_rgba(0,0,0,0.08)] backdrop-blur-md transition-opacity duration-200 motion-reduce:transition-none lg:bottom-6 lg:right-8 ${
202	          metasVisible ? 'opacity-100' : 'pointer-events-none opacity-0'
203	        }`}
