1	/**
2	 * @module features/tv-dashboard/ui/TvStoreCard
3	 *
4	 * Card de loja do Painel TV (design.md §4): vendas do dia (ou defasadas
5	 * com selo honesto), barra de % meta, mini-stats e borda RAG com
6	 * redundância não-cromática (glow + chip de estado). Largura fluida
7	 * (1 col mobile → 2 sm → 3 xl); tipografia em clamp() (referência a 1920px).
8	 * Chassi v2: glass premium (vidro branco + gradiente interno dourado sutil).
9	 */
10	
11	import { ArrowDownRight, ArrowUpRight } from 'lucide-react';
12	import type { TvFreshnessLevel, TvStoreData } from '../model/types';
13	import { formatCompactBRL, parseBrDateTime, parseIsoDateLocal } from '../model/tvMath';
14	import {
15	  TvDeltaChip,
16	  TvMetaBar,
17	  TvSourceChip,
18	  TvStateChip,
19	  TvStockBadge,
20	} from './TvChips';
21	import {
22	  WEEKDAY_ABBR,
23	  expectedPctNow,
24	  formatInt,
25	  formatTicketBRL,
26	  formatTimeHHMM,
27	  formatWeekdayDayMonth,
28	  metaBarColorFromRatio,
29	} from './tvFormat';
30	import { useCountUp } from './useCountUp';
31	
32	interface TvStoreCardProps {
33	  store: TvStoreData;
34	  /** Freshness consolidado da fonte de vendas live (chip "ao vivo"/"atrasado"). */
35	  liveLevel: TvFreshnessLevel;
36	  now: Date;
37	}
38	
39	/**
40	 * Borda + glow por estado RAG (design.md §4 — sinal lível a 5m).
41	 * Normal = vidro calmo; ÂMBAR/CRÍTICO ganham borda colorida + glow suave.
42	 */
43	const RAG_FRAME: Record<TvStoreData['rag'], string> = {
44	  ok: 'border border-[#57715B]/10 shadow-[0_8px_32px_rgba(0,0,0,0.06)]',
45	  amber: 'border-2 border-amber-400/60 shadow-[0_8px_32px_rgba(245,158,11,0.18)]',
46	  red: 'border-2 border-red-400/70 shadow-[0_8px_32px_rgba(229,72,77,0.15)]',
47	};
48	
49	/** Card de loja: cobre canal Degust live e Linx defasado. */
50	export function TvStoreCard({ store, liveLevel, now }: TvStoreCardProps) {
51	  const { vendas, metaDia, channel } = store;
52	  const isLive = channel === 'degust-live';
53	  const valorAnim = useCountUp(vendas?.valor ?? 0);
54	  const cuponsAnim = Math.round(useCountUp(vendas?.cupons ?? 0));
55	
56	  // Barra: preenchimento = % do dia COMPLETO; tick pró-rata só no canal live
57	  const fullDayPct =
58	    vendas != null && metaDia != null && metaDia > 0
59	      ? (vendas.valor / metaDia) * 100
60	      : null;
61	  const expected = isLive ? expectedPctNow(now) : null;
62	  const barColor = isLive
63	    ? metaBarColorFromRatio(store.pctMeta != null ? store.pctMeta / 100 : null, now)
64	    : 'sage';
65	
66	  const bipTime = formatTimeHHMM(store.movimentacao.ultimaBipagem);
67	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
68	
69	  // Caption sob as vendas (design.md §4 item 4)
70	  let caption: string;
71	  if (vendas == null) {
72	    caption = 'sem dado de venda disponível';
73	  } else if (isLive) {
74	    // `ultima_atualizacao` do Degust vem "DD/MM/YYYY HH:mm:ss" — parser
75	    // dedicado pt-BR (new Date() falha para dia > 12).
76	    const upd = formatTimeHHMM(parseBrDateTime(vendas.atualizadoEm));
77	    caption = `hoje${upd ? ` · atualizado ${upd}` : ''}${bipTime ? ` · bip ${bipTime}` : ''}`;
78	  } else {
79	    caption = `${refDate ? formatWeekdayDayMonth(refDate) : ''} — último dia com dados${bipTime ? ` · bip ${bipTime}` : ''}`;
80	  }
81	
82	  return (
83	    <section
84	      className={`relative overflow-hidden rounded-[2rem] bg-white/60 p-4 backdrop-blur-xl saturate-150 transition-[border-color,box-shadow] [transition-duration:400ms] motion-reduce:transition-none lg:p-5 ${RAG_FRAME[store.rag]}`}
85	      data-testid="tv-store-card"
86	      data-rag={store.rag}
87	    >
88	      {/* Gradiente interno sutil (assinatura glass premium) */}
89	      <div
90	        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
91	        aria-hidden
92	      />
93	
94	      <div className="relative z-10 flex h-full flex-col">
95	        {/* Header: nome + chips (quebram linha quando não cabem) */}
96	        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1.5">
97	          <h2 className="min-w-0 truncate font-momma text-[clamp(1rem,1.45vw,2.625rem)] font-semibold leading-tight text-[#2D362E]">
98	            {store.nome}
99	          </h2>
100	          <div className="flex shrink-0 flex-wrap items-center justify-end gap-1.5 lg:gap-2">
101	            <TvStateChip rag={store.rag} />
102	            <TvStockBadge estoque={store.estoque} />
103	            <TvSourceChip
104	              channel={channel}
105	              liveLevel={liveLevel}
106	              laggedDate={vendas?.dataReferencia ?? null}
107	            />
108	          </div>
109	        </div>
110	
111	        {/* Vendas (referência 64px @1920) + delta */}
112	        <div className="mt-1.5 flex flex-wrap items-end gap-x-4 gap-y-1">
113	          <span
114	            className={`font-momma text-[clamp(2rem,3.35vw,6rem)] font-bold leading-none tabular-nums ${vendas ? 'text-[#2D362E]' : 'text-[#7C887E]'}`}
115	            data-testid="tv-store-sales"
116	          >
117	            {vendas ? formatCompactBRL(valorAnim) : '—'}
118	          </span>
119	          {store.deltaSemana != null && refDate != null && (
120	            <span className="pb-1">
121	              <TvDeltaChip
122	                delta={store.deltaSemana}
123	                weekdayLabel={WEEKDAY_ABBR[refDate.getDay()]}
124	                size="card"
125	              />
126	            </span>
127	          )}
128	        </div>
129	        <p className="mt-1 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-tight text-[#7C887E]">
130	          {caption}
131	        </p>
132	
133	        {/* Barra de meta */}
134	        <div className="mt-2">
135	          <TvMetaBar
136	            fillPct={fullDayPct}
137	            expectedPct={fullDayPct != null ? expected : null}
138	            color={barColor}
139	            size="card"
140	          />
141	          <p className="mt-1.5 font-momma text-[clamp(0.75rem,1.15vw,2rem)] leading-tight">
142	            {fullDayPct != null ? (
143	              isLive ? (
144	                <>
145	                  <span className="font-medium text-[#5F6F63]">
146	                    {Math.round(fullDayPct)}% da meta
147	                  </span>
148	                  <span className="text-[#7C887E]"> · esperado {expected}%</span>
149	                </>
150	              ) : (
151	                <span className="font-medium text-[#5F6F63]">
152	                  {Math.round(fullDayPct)}% da meta de{' '}
153	                  {refDate ? WEEKDAY_ABBR[refDate.getDay()] : '—'}
154	                </span>
155	              )
156	            ) : (
157	              <span className="text-[#7C887E]">sem meta cadastrada</span>
158	            )}
159	          </p>
160	        </div>
161	
162	        {/* Mini-stats */}
163	        <div className="mt-auto grid grid-cols-3 gap-2 pt-3 sm:gap-4">
164	          <div>
165	            <p className="font-momma text-[clamp(0.75rem,1.15vw,2rem)] font-medium uppercase tracking-wider text-[#5F6F63]">
166	              CUPONS
167	            </p>
168	            <p className="mt-0.5 font-momma text-[clamp(1.125rem,1.7vw,3rem)] font-medium leading-none text-[#2D362E] tabular-nums">
169	              {vendas?.cupons != null ? formatInt(cuponsAnim) : '—'}
170	            </p>
171	          </div>
172	          <div>
173	            <p className="font-momma text-[clamp(0.75rem,1.15vw,2rem)] font-medium uppercase tracking-wider text-[#5F6F63]">
174	              TICKET
175	            </p>
176	            <p className="mt-0.5 font-momma text-[clamp(1.125rem,1.7vw,3rem)] font-medium leading-none text-[#2D362E] tabular-nums">
177	              {vendas?.ticketMedio != null ? formatTicketBRL(vendas.ticketMedio) : '—'}
178	            </p>
179	          </div>
180	          <div>
181	            <p className="font-momma text-[clamp(0.75rem,1.15vw,2rem)] font-medium uppercase tracking-wider text-[#5F6F63]">
182	              FLUXO
183	            </p>
184	            <p className="mt-0.5 flex items-center gap-1 font-momma text-[clamp(1rem,1.45vw,2.625rem)] font-medium leading-none text-[#2D362E] tabular-nums">
185	              <ArrowUpRight className="h-[0.8em] w-[0.8em] shrink-0 text-[#5F6F63]" aria-hidden />
186	              {store.movimentacao.entradas}
187	              <ArrowDownRight
188	                className="ml-2 h-[0.8em] w-[0.8em] shrink-0 text-[#5F6F63]"
189	                aria-hidden
190	              />
191	              {store.movimentacao.saidas}
192	            </p>
193	          </div>
194	        </div>
195	      </div>
196	    </section>
197	  );
198	}
