1	/**
2	 * @module features/tv-dashboard/ui/TvChips
3	 *
4	 * Blocos visuais compartilhados do Painel TV: chip de delta semanal,
5	 * chip de fonte (ao vivo / atrasado / defasado Linx), chip de estado RAG,
6	 * badge de estoque e barra de % meta com tick de esperado.
7	 * Linguagem v2 (glassmorphism Momma): design.md §1.3–§1.6, §3 e §4.
8	 * v2.1: tipografia fluida clamp() (referência a 1920px) e ícones em `em`
9	 * (escalam junto com o texto do chip).
10	 */
11	
12	import {
13	  ArrowDown,
14	  ArrowUp,
15	  CalendarClock,
16	  Check,
17	  OctagonAlert,
18	  RefreshCw,
19	  TriangleAlert,
20	} from 'lucide-react';
21	import type {
22	  TvFreshnessLevel,
23	  TvRagStatus,
24	  TvSalesChannel,
25	  TvStockAlertSummary,
26	} from '../model/types';
27	import { formatLaggedDateLabel } from '../model/tvMath';
28	import { clampPct, formatDeltaPct, type TvBarColor } from './tvFormat';
29	
30	// ─────────────────────────────────────────────────────────────────────────────
31	// Delta semanal (vs mesmo dia da semana passada — nunca "ontem")
32	// ─────────────────────────────────────────────────────────────────────────────
33	
34	interface TvDeltaChipProps {
35	  /** Delta % vs mesmo dia da semana anterior. */
36	  delta: number;
37	  /** Abreviação do dia comparado ("qua."). */
38	  weekdayLabel: string;
39	  /** Tamanho: hero (referência 28px a 1920px) ou card de loja (24px a 1920px). */
40	  size: 'hero' | 'card';
41	}
42	
43	/**
44	 * Chip de delta semanal. Neutro (pill sage suave) sempre — exceto delta
45	 * ≤ −15%, que vira âmbar (design.md §3 zona 1). Positivo nunca ganha verde.
46	 */
47	export function TvDeltaChip({ delta, weekdayLabel, size }: TvDeltaChipProps) {
48	  const isAlert = delta <= -15;
49	  const colorCls = isAlert
50	    ? 'bg-amber-50 text-amber-600'
51	    : 'bg-[#57715B]/8 text-[#5F6F63]';
52	  const textCls =
53	    size === 'hero'
54	      ? 'text-[clamp(0.875rem,1.45vw,2.625rem)]'
55	      : 'text-[clamp(0.8125rem,1.25vw,2.25rem)]';
56	  const Icon = delta < 0 ? ArrowDown : ArrowUp;
57	  return (
58	    <span
59	      className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 font-momma font-medium tabular-nums leading-none lg:px-4 lg:py-1.5 ${textCls} ${colorCls}`}
60	      data-testid="tv-delta-chip"
61	    >
62	      <Icon className="h-[1em] w-[1em] shrink-0" aria-hidden />
63	      {formatDeltaPct(delta)} vs {weekdayLabel}
64	    </span>
65	  );
66	}
67	
68	// ─────────────────────────────────────────────────────────────────────────────
69	// Chip de fonte (freshness honesta — design.md §4 item 1)
70	// ─────────────────────────────────────────────────────────────────────────────
71	
72	interface TvSourceChipProps {
73	  channel: TvSalesChannel;
74	  /** Freshness da fonte live (ignorado para canal Linx). */
75	  liveLevel: TvFreshnessLevel;
76	  /** Dia de referência (YYYY-MM-DD) do dado defasado Linx, ou null. */
77	  laggedDate?: string | null;
78	}
79	
80	/**
81	 * Chip de fonte do card: Degust fresco → "✓ ao vivo" (emerald); Degust
82	 * atrasado → "⟳ atrasado" (âmbar); Linx → selo NEUTRO "até DD/MM"
83	 * (defasagem esperada não é alarme).
84	 */
85	export function TvSourceChip({ channel, liveLevel, laggedDate }: TvSourceChipProps) {
86	  if (channel === 'linx-lagged') {
87	    return (
88	      <span
89	        className="inline-flex items-center gap-1.5 rounded-full bg-[#57715B]/8 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-[#5F6F63]"
90	        data-testid="tv-source-chip-lagged"
91	      >
92	        <CalendarClock className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
93	        {laggedDate ? formatLaggedDateLabel(laggedDate) : 'sem dados'}
94	      </span>
95	    );
96	  }
97	  if (liveLevel === 'fresh') {
98	    return (
99	      <span
100	        className="inline-flex items-center gap-1.5 rounded-full bg-emerald-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-emerald-600"
101	        data-testid="tv-source-chip-live"
102	      >
103	        <Check className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
104	        ao vivo
105	      </span>
106	    );
107	  }
108	  return (
109	    <span
110	      className="inline-flex items-center gap-1.5 rounded-full border border-amber-400/40 bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600"
111	      data-testid="tv-source-chip-stale"
112	    >
113	      <RefreshCw className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
114	      atrasado
115	    </span>
116	  );
117	}
118	
119	// ─────────────────────────────────────────────────────────────────────────────
120	// Chip de estado RAG (redundância não-cromática lível a 3m)
121	// ─────────────────────────────────────────────────────────────────────────────
122	
123	/** Chip "⚠ ATENÇÃO" / "⛔ CRÍTICO" do header do card. Nulo em estado ok. */
124	export function TvStateChip({ rag }: { rag: TvRagStatus }) {
125	  if (rag === 'ok') return null;
126	  if (rag === 'red') {
127	    return (
128	      <span
129	        className="inline-flex items-center gap-1.5 rounded-full bg-red-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-red-600"
130	        data-testid="tv-state-chip-red"
131	      >
132	        <OctagonAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
133	        CRÍTICO
134	      </span>
135	    );
136	  }
137	  return (
138	    <span
139	      className="inline-flex items-center gap-1.5 rounded-full bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600"
140	      data-testid="tv-state-chip-amber"
141	    >
142	      <TriangleAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
143	      ATENÇÃO
144	    </span>
145	  );
146	}
147	
148	// ─────────────────────────────────────────────────────────────────────────────
149	// Badge de estoque (contagem; vermelho absorve âmbar quando há ambos)
150	// ─────────────────────────────────────────────────────────────────────────────
151	
152	/**
153	 * Badge de alerta de estoque do header. Se houver zerados E abaixo do
154	 * mínimo, mostra só o vermelho com a SOMA (design.md §4 item 1).
155	 */
156	export function TvStockBadge({ estoque }: { estoque: TvStockAlertSummary }) {
157	  const total = estoque.zerados + estoque.abaixoMinimo;
158	  if (total === 0) return null;
159	  if (estoque.zerados > 0) {
160	    return (
161	      <span
162	        className="inline-flex items-center gap-1.5 rounded-full bg-red-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-red-600 tabular-nums"
163	        data-testid="tv-stock-badge-red"
164	      >
165	        <OctagonAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
166	        {total}
167	      </span>
168	    );
169	  }
170	  return (
171	    <span
172	      className="inline-flex items-center gap-1.5 rounded-full bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600 tabular-nums"
173	      data-testid="tv-stock-badge-amber"
174	    >
175	      <TriangleAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
176	      {total}
177	    </span>
178	  );
179	}
180	
181	// ─────────────────────────────────────────────────────────────────────────────
182	// Barra de % meta com tick de "esperado agora"
183	// ─────────────────────────────────────────────────────────────────────────────
184	
185	const BAR_FILL_CLS: Record<TvBarColor, string> = {
186	  sage: 'bg-gradient-to-r from-[#57715B] to-[#4a6250]',
187	  amber: 'bg-gradient-to-r from-amber-400 to-amber-500',
188	  red: 'bg-gradient-to-r from-red-400 to-red-500',
189	};
190	
191	interface TvMetaBarProps {
192	  /** % do dia COMPLETO da meta já atingido (preenchimento), ou null. */
193	  fillPct: number | null;
194	  /** Posição do tick de "esperado agora" (0–100), ou null para ocultar. */
195	  expectedPct: number | null;
196	  /** Cor semântica do preenchimento (estado de venda — design.md §1.6). */
197	  color: TvBarColor;
198	  /** Altura da barra: hero 14→20px, card 10→12px (mobile → lg+). */
199	  size: 'hero' | 'card';
200	}
201	
202	/**
203	 * Barra horizontal de % meta: trilha sage suave (`#57715B/10`),
204	 * preenchimento em gradiente por estado de venda e tick DOURADO de
205	 * "esperado agora" (pró-rata). Transição de width 600ms ease-out (§8.1.3).
206	 */
207	export function TvMetaBar({ fillPct, expectedPct, color, size }: TvMetaBarProps) {
208	  const heightCls = size === 'hero' ? 'h-3.5 lg:h-5' : 'h-2.5 lg:h-3';
209	  const tick =
210	    size === 'hero'
211	      ? { width: 3, height: 28, offset: -4 }
212	      : { width: 2, height: 20, offset: -4 };
213	  return (
214	    <div
215	      className={`relative w-full rounded-full bg-[#57715B]/10 ${heightCls}`}
216	      data-testid="tv-meta-bar"
217	    >
218	      {fillPct != null && (
219	        <div
220	          className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${BAR_FILL_CLS[color]}`}
221	          style={{ width: `${clampPct(fillPct)}%` }}
222	          data-testid="tv-meta-bar-fill"
223	        />
224	      )}
225	      {expectedPct != null && (
226	        <div
227	          className="absolute rounded-full bg-[#C5A065]"
228	          style={{
229	            left: `calc(${clampPct(expectedPct)}% - ${tick.width / 2}px)`,
230	            top: tick.offset,
231	            width: tick.width,
232	            height: tick.height,
233	          }}
234	          data-testid="tv-meta-bar-tick"
235	        />
236	      )}
237	    </div>
238	  );
239	}
