1	/**
2	 * @module features/tv-dashboard/ui/tvFormat
3	 *
4	 * Formatadores de APRESENTAÇÃO do Painel TV (camada UI).
5	 * Regras de negócio/agregação vivem em `../model/tvMath` — aqui só render.
6	 */
7	
8	import { businessDayFraction } from '../model/tvMath';
9	
10	/** Cor semântica da barra de meta (design.md §1.6 — estado de VENDA). */
11	export type TvBarColor = 'sage' | 'amber' | 'red';
12	
13	/** Abreviações pt-BR dos dias da semana (índice = `Date.getDay()`). */
14	export const WEEKDAY_ABBR = [
15	  'dom.',
16	  'seg.',
17	  'ter.',
18	  'qua.',
19	  'qui.',
20	  'sex.',
21	  'sáb.',
22	] as const;
23	
24	/** Hora local `HH:MM` (sem segundos — design.md §1.5), ou null sem dado. */
25	export function formatTimeHHMM(value: Date | string | null | undefined): string | null {
26	  if (value == null) return null;
27	  const d = value instanceof Date ? value : new Date(value);
28	  if (Number.isNaN(d.getTime())) return null;
29	  return d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
30	}
31	
32	/** Contagem inteira com separador de milhar pt-BR ("1.240"). */
33	export function formatInt(value: number): string {
34	  return Math.round(value).toLocaleString('pt-BR');
35	}
36	
37	/** Ticket médio sempre com 2 decimais ("R$ 38,50" — design.md §1.5). */
38	export function formatTicketBRL(value: number): string {
39	  return `R$ ${value.toLocaleString('pt-BR', {
40	    minimumFractionDigits: 2,
41	    maximumFractionDigits: 2,
42	  })}`;
43	}
44	
45	/** Delta com sinal e seta textual implícita ("12%" — sinal vem do ícone). */
46	export function formatDeltaPct(delta: number): string {
47	  return `${Math.abs(Math.round(delta))}%`;
48	}
49	
50	/** Rótulo "ter. 03/06" para o dia de referência de canal defasado. */
51	export function formatWeekdayDayMonth(date: Date): string {
52	  const dd = String(date.getDate()).padStart(2, '0');
53	  const mm = String(date.getMonth() + 1).padStart(2, '0');
54	  return `${WEEKDAY_ABBR[date.getDay()]} ${dd}/${mm}`;
55	}
56	
57	/** "há 12 min" / "há 3h" para timestamps recentes; null sem dado. */
58	export function formatAgoLabel(
59	  value: Date | string | null | undefined,
60	  now: Date,
61	): string | null {
62	  if (value == null) return null;
63	  const d = value instanceof Date ? value : new Date(value);
64	  if (Number.isNaN(d.getTime())) return null;
65	  const diffMin = Math.max(0, Math.floor((now.getTime() - d.getTime()) / 60_000));
66	  if (diffMin < 60) return `há ${diffMin} min`;
67	  return `há ${Math.floor(diffMin / 60)}h`;
68	}
69	
70	/**
71	 * Cor da barra de % meta a partir do ratio pró-rata (`%real / %esperado`,
72	 * em fração: 1.0 = exatamente no ritmo). Regra do design.md §1.6:
73	 * sage ≥ 0,9 · âmbar 0,75–0,9 · vermelho abaixo de 0,6 após 12:00
74	 * (entre 0,6 e 0,75 fica âmbar).
75	 * Ratio nulo (sem meta / antes da janela) fica sage — barra neutra.
76	 */
77	export function metaBarColorFromRatio(ratio: number | null, now: Date): TvBarColor {
78	  if (ratio == null) return 'sage';
79	  if (ratio >= 0.9) return 'sage';
80	  if (ratio >= 0.75) return 'amber';
81	  if (ratio < 0.6 && now.getHours() >= 12) return 'red';
82	  return 'amber';
83	}
84	
85	/** % esperado AGORA da meta do dia (posição do tick pró-rata), 0–100. */
86	export function expectedPctNow(now: Date): number {
87	  return Math.round(businessDayFraction(now) * 100);
88	}
89	
90	/** Limita um percentual de preenchimento de barra ao intervalo [0, 100]. */
91	export function clampPct(pct: number | null): number {
92	  if (pct == null || Number.isNaN(pct)) return 0;
93	  return Math.max(0, Math.min(100, pct));
94	}
