96	
97	        {/* Produção (referência 64px @1920) */}
98	        <div className="mt-1.5 flex items-end gap-3">
99	          <span
100	            className={`font-momma text-[clamp(2rem,3.35vw,6rem)] font-bold leading-none tabular-nums ${producao ? 'text-[#2D362E]' : 'text-[#7C887E]'}`}
