1	/*
2	 * Animações do Painel TV (/tv) — lista FECHADA do design.md §8.1 (v2) —
3	 * mais o viewport-lock responsivo (v2.1). Só transform/opacity nas
4	 * animações (pixel-shift anti burn-in, fades, dots) — nenhuma cor vive
5	 * aqui. Importado apenas por TvDashboard.page.tsx; nada vaza para o
6	 * design system.
7	 */
8	
9	/*
10	 * v2.1 — viewport-lock de TV/monitor grande (design.md §2).
11	 * O painel é uma página fluida normal (scroll natural em telas menores).
12	 * Quando a viewport tem largura ≥1280px E altura ≥1000px (TV 1080p+,
13	 * monitores grandes, kiosk fullscreen), o conteúdo TRAVA na viewport:
14	 * zero scroll, linha de lojas absorve a altura restante. A condição de
15	 * altura é essencial: em 1366×768 ou janela desktop não-maximizada o
16	 * conteúdo NÃO cabe e deve fluir — travar clipparia cards.
17	 */
18	@media (min-width: 1280px) and (min-height: 1000px) {
19	  .tv-lock-viewport {
20	    height: 100dvh;
21	    overflow: hidden;
22	  }
23	
24	  .tv-lock-fill {
25	    height: 100%;
26	  }
27	
28	  .tv-lock-grow {
29	    flex: 1 1 0%;
30	    min-height: 0;
31	  }
32	}
33	
34	@media (prefers-reduced-motion: no-preference) {
35	  /* §8.1.5 — pixel-shift anti burn-in: ciclo de 16 min (960s), passos de
36	     1-2px com interpolação de ~2s (0.2% de 960s ≈ 1,9s) em cada troca. */
37	  @keyframes tv-pixel-shift {
38	    0% {
39	      transform: translate(0, 0);
40	    }
41	    24.8% {
42	      transform: translate(0, 0);
43	    }
44	    25% {
45	      transform: translate(1px, 1px);
46	    }
47	    49.8% {
48	      transform: translate(1px, 1px);
49	    }
50	    50% {
51	      transform: translate(0, 2px);
52	    }
53	    74.8% {
54	      transform: translate(0, 2px);
55	    }
56	    75% {
57	      transform: translate(-1px, 1px);
58	    }
59	    99.8% {
60	      transform: translate(-1px, 1px);
61	    }
62	    100% {
63	      transform: translate(0, 0);
64	    }
65	  }
66	
67	  .tv-pixel-shift {
68	    animation: tv-pixel-shift 960s ease-in-out infinite;
69	  }
70	
71	  /* §8.1.2 — fade-in de exceção nova (uma única vez) */
72	  @keyframes tv-fade-in {
73	    from {
74	      opacity: 0;
75	      transform: translateY(6px);
76	    }
77	    to {
78	      opacity: 1;
79	      transform: translateY(0);
80	    }
81	  }
82	
83	  .tv-fade-in {
84	    animation: tv-fade-in 300ms ease-out both;
85	  }
86	
87	  /* §7 — conteúdo entra com fade único de 300ms após o primeiro load */
88	  @keyframes tv-content-enter {
89	    from {
90	      opacity: 0;
91	    }
92	    to {
93	      opacity: 1;
94	    }
95	  }
96	
97	  .tv-content-enter {
98	    animation: tv-content-enter 300ms ease-out both;
99	  }
100	
101	  /* §7 — loading inicial: 3 pontos que acendem em sequência (1×/600ms),
102	     único movimento permitido fora do estado carregado. */
103	  @keyframes tv-dot {
104	    0%,
105	    100% {
106	      opacity: 0.2;
107	    }
108	    33% {
109	      opacity: 1;
110	    }
111	  }
112	
113	  .tv-dot {
114	    animation: tv-dot 1800ms steps(3, jump-none) infinite;
115	  }
116	
117	  .tv-dot:nth-child(2) {
118	    animation-delay: 600ms;
119	  }
120	
121	  .tv-dot:nth-child(3) {
122	    animation-delay: 1200ms;
123	  }
124	}
125	
126	/* §8.1.3/§8.1.4 — transições de barra e de estado RAG valem mesmo com
127	   reduced-motion? Não: §8.1.7 manda trocar seco. As classes utilitárias de
128	   transição são aplicadas via Tailwind nos componentes; aqui apenas as
129	   desligamos sob reduced-motion. */
130	@media (prefers-reduced-motion: reduce) {
131	  .tv-pixel-shift,
132	  .tv-fade-in,
133	  .tv-content-enter,
134	  .tv-dot {
135	    animation: none;
136	  }
137	}
