160	  degustCodeToLoja: Map<number, number>;
161	  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
162	  linxLojaIds: number[];
163	  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
164	  factoryLojaId: number | null;
165	}
166	
167	function isFactoryTipo(tipo: string | null): boolean {
168	  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
169	  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
170	}
