172	/** Carrega o contexto (exportado para o `useTvStoreDetail` compartilhar cache). */
173	export async function fetchTvContext(): Promise<TvContext> {
174	  const [lojasRes, degustRes] = await Promise.all([
175	    supabase
176	      .from('lojas')
177	      .select('id, nome, tipo')
178	      .eq('ativo', true)
179	      .order('id'),
180	    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
181	  ]);
182	  if (lojasRes.error) throw lojasRes.error;
183	  if (degustRes.error) throw degustRes.error;
184	
185	  const lojas: TvLoja[] = lojasRes.data ?? [];
186	  const degustLojaIds = new Set<number>();
187	  const degustCodeToLoja = new Map<number, number>();
188	  for (const row of degustRes.data ?? []) {
189	    degustLojaIds.add(row.loja_id);
190	    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
191	  }
192	
193	  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
194	  const linxLojaIds = lojas
195	    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
196	    .map((l) => l.id);
197	
198	  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
199	}
