238	// ─────────────────────────────────────────────────────────────────────────────
239	// Vendas defasadas (Linx via historico_vendas — último dia disponível)
240	// ─────────────────────────────────────────────────────────────────────────────
241	
242	interface LaggedSales {
243	  lojaId: number;
244	  /** Último dia com venda registrada (YYYY-MM-DD). */
245	  dataReferencia: string;
246	  valor: number;
247	  quantidade: number;
248	  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
249	  valorSemanaAnterior: number | null;
250	  /** Valor do DIA ANTERIOR ao dia de referência (dias completos), ou null. */
251	  valorDiaAnterior: number | null;
252	}
253	
254	async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
255	  // 1) Último dia com dado para a loja
256	  const { data: latest, error: latestErr } = await supabase
257	    .from('historico_vendas')
258	    .select('data')
259	    .eq('loja_id', lojaId)
260	    .order('data', { ascending: false })
261	    .limit(1);
262	  if (latestErr) throw latestErr;
263	  const refDate = latest?.[0]?.data;
264	  if (!refDate) return null;
265	
266	  const weekAgoDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
267	  const dayBeforeDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -1));
268	
269	  // 2) Vendas do dia de referência + bases de comparação (dia anterior =
270	  //    comparativo PRINCIPAL v3; mesma semana = secundário)
271	  const [curRes, weekRes, dayRes] = await Promise.all([
272	    supabase
273	      .from('historico_vendas')
274	      .select('valor_total, quantidade')
275	      .eq('loja_id', lojaId)
276	      .eq('data', refDate)
277	      .limit(2000),
278	    supabase
279	      .from('historico_vendas')
280	      .select('valor_total')
281	      .eq('loja_id', lojaId)
282	      .eq('data', weekAgoDate)
283	      .limit(2000),
284	    supabase
285	      .from('historico_vendas')
286	      .select('valor_total')
287	      .eq('loja_id', lojaId)
288	      .eq('data', dayBeforeDate)
289	      .limit(2000),
290	  ]);
291	  if (curRes.error) throw curRes.error;
292	  if (weekRes.error) throw weekRes.error;
293	  if (dayRes.error) throw dayRes.error;
294	
295	  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
296	  const quantidade = (curRes.data ?? []).reduce(
297	    (s, r) => s + (r.quantidade ?? 0),
298	    0,
299	  );
300	  const sumOrNull = (rows: Array<{ valor_total: number | null }> | null) => {
301	    const list = rows ?? [];
302	    return list.length > 0
303	      ? list.reduce((s, r) => s + (r.valor_total ?? 0), 0)
304	      : null;
305	  };
306	
307	  return {
308	    lojaId,
309	    dataReferencia: refDate,
310	    valor,
311	    quantidade,
312	    valorSemanaAnterior: sumOrNull(weekRes.data),
313	    valorDiaAnterior: sumOrNull(dayRes.data),
314	  };
315	}
316	
317	async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
318	  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
319	  return results.filter((r): r is LaggedSales => r !== null);
320	}
