322	// ─────────────────────────────────────────────────────────────────────────────
323	// Bases de comparação Degust: ONTEM (principal v3) + mesmo dia da semana
324	// passada (secundário) — uma única query em degust_vendas_diarias
325	// ─────────────────────────────────────────────────────────────────────────────
326	
327	interface DegustReferenceSales {
328	  /** R$ por loja ONTEM (base do delta principal, pró-rateada no uso). */
329	  yesterday: Map<number, number>;
330	  /** R$ por loja no MESMO DIA da semana passada (delta secundário). */
331	  lastWeek: Map<number, number>;
332	}
333	
334	async function fetchDegustReference(ctx: TvContext): Promise<DegustReferenceSales> {
335	  const yesterday = new Map<number, number>();
336	  const lastWeek = new Map<number, number>();
337	  const ids = [...ctx.degustLojaIds];
338	  if (ids.length === 0) return { yesterday, lastWeek };
339	  const now = new Date();
340	  const yesterdayDate = toIsoDateLocal(addDays(now, -1));
341	  const lastWeekDate = toIsoDateLocal(addDays(now, -7));
342	  // Paginado: degust_vendas_diarias é linha-por-produto (2 dias × N lojas
343	  // pode passar de 1000 — o PostgREST cortaria silenciosamente).
344	  const rows = await fetchAllPages((from, to) =>
345	    supabase
346	      .from('degust_vendas_diarias')
347	      .select('loja_id, valor_total, data')
348	      .in('data', [yesterdayDate, lastWeekDate])
349	      .in('loja_id', ids)
350	      .order('id')
351	      .range(from, to),
352	  );
353	  for (const row of rows) {
354	    const target = row.data === yesterdayDate ? yesterday : lastWeek;
355	    target.set(row.loja_id, (target.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
356	  }
357	  return { yesterday, lastWeek };
358	}
