525	async function loadComprasRange(range: TvDateRange): Promise<ComprasByLoja> {
526	  // Campo de data canônico: `data_nota` (emissão) — mesmo critério do DRE.
527	  // Status válido = tudo menos `erro` (NF_COUNTED_STATUSES); transferências
528	  // internas "Momma Doces" excluídas (não são compra). Paginado: um mês de
529	  // NFs pode passar de 1000 linhas.
530	  const rows = await fetchAllPages((from, to) =>
531	    supabase
532	      .from('notas_fiscais')
533	      .select('loja_id, valor_total')
534	      .gte('data_nota', range.from)
535	      .lte('data_nota', range.to)
536	      .in('status', [...NF_COUNTED_STATUSES])
537	      .not('fornecedor', 'ilike', NF_TRANSFER_SUPPLIER_PATTERN)
538	      .order('id')
539	      .range(from, to),
540	  );
541	  return aggregateCompras(rows);
542	}
