37	  TV_DETAIL_FEED_LIMIT,
38	  aggregateMovements,
39	  aggregatePerdas,
40	  buildStockSummary,
41	  fetchAllPages,
42	  mapFeedRow,
43	  previousRangeSameDuration,
44	  rangeToLocalDayBounds,
45	  relativeDelta,
