13	
14	/**
15	 * Separa a linha em texto principal + valor à direita, por tipo de exceção
16	 * (design.md §6.1 — anatomia da linha).
17	 */
18	function splitException(ex: TvException): { text: string; value: string } {
19	  switch (ex.kind) {
20	    case 'stock-out':
21	      return {
22	        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
23	        value: '0 un',
24	      };
25	    case 'stock-low':
26	      return {
27	        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
28	        value: `${ex.quantidade ?? 0} · mín ${ex.quantidadeMinima ?? 0}`,
29	      };
30	    case 'no-movement': {
31	      const m = ex.message.match(/há \d+\s?h/);
32	      return {
33	        text: `${ex.lojaNome ?? 'Loja'} — sem bipagem`,
34	        value: m ? m[0] : '',
35	      };
36	    }
37	    case 'stale-data': {
38	      const m = ex.message.match(/desde \d{2}:\d{2}/);
39	      return {
40	        text: `${ex.lojaNome ?? 'Venda live'} — dado atrasado`,
41	        value: m ? m[0] : '',
42	      };
43	    }
44	  }
45	}
