148	 * - `week`: segunda-feira da semana corrente → hoje;
149	 * - `month`: dia 1º do mês corrente → hoje.
150	 */
151	export function periodRange(period: TvPeriod, now: Date): TvDateRange {
152	  const today = toIsoDateLocal(now);
153	  if (period === 'today') return { from: today, to: today };
154	  if (period === 'week') {
155	    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
156	    const dowFromMonday = (now.getDay() + 6) % 7;
157	    const monday = addDays(now, -dowFromMonday);
158	    return { from: toIsoDateLocal(monday), to: today };
159	  }
160	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
161	  return { from: toIsoDateLocal(firstOfMonth), to: today };
162	}
163	
164	/**
165	 * Período ANTERIOR equivalente para comparativos do filtro global:
166	 * - `today`: ontem → ontem;
167	 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
168	 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
169	 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
170	 */
171	export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
172	  if (period === 'today') {
173	    const yesterday = toIsoDateLocal(addDays(now, -1));
174	    return { from: yesterday, to: yesterday };
175	  }
176	  if (period === 'week') {
177	    const dowFromMonday = (now.getDay() + 6) % 7;
178	    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
179	    return {
180	      from: toIsoDateLocal(mondayLastWeek),
181	      to: toIsoDateLocal(addDays(now, -7)),
182	    };
183	  }
184	  const y = now.getFullYear();
185	  const m = now.getMonth();
186	  const firstPrev = new Date(y, m - 1, 1);
187	  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
188	  const lastDayPrevMonth = new Date(y, m, 0).getDate();
189	  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
190	  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
191	}
192	
193	/**
194	 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
195	 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
196	 */
197	export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
198	  const from = parseIsoDateLocal(range.from);
199	  const to = parseIsoDateLocal(range.to);
200	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
201	  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
202	  return {
203	    from: toIsoDateLocal(addDays(from, -days)),
204	    to: toIsoDateLocal(addDays(to, -days)),
205	  };
206	}
207	
208	/**
209	 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
210	 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
211	 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
212	 * (exclusivo — usar `.lt`, nunca `.lte`).
213	 */
214	export function rangeToLocalDayBounds(range: TvDateRange): {
215	  startIso: string;
216	  endExclusiveIso: string;
217	} {
218	  const start = parseIsoDateLocal(range.from);
219	  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
220	  return {
221	    startIso: start.toISOString(),
222	    endExclusiveIso: endExclusive.toISOString(),
223	  };
224	}
