510	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
511	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
512	 * Valores negativos preservam o sinal ("-R$ 1,2k").
513	 */
514	export function formatCompactBRL(value: number): string {
515	  const sign = value < 0 ? '-' : '';
516	  const abs = Math.abs(value);
517	  // Bump pra M quando o arredondamento em k chegaria a 1000k
518	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
519	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
520	  }
521	  if (abs >= 1_000) {
522	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
523	  }
524	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
525	}
