373	/**
374	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
375	 *
376	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
377	 *   não faz sentido alertar madrugada sem bipagem.
378	 * - A referência é clampada ao início da janela de hoje: se a última
379	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
380	 */
381	export function hoursWithoutMovementInWindow(
382	  lastMovementAt: Date | string | null,
383	  now: Date,
384	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
385	): number | null {
386	  const fraction = businessDayFraction(now, hours);
387	  if (fraction <= 0 || fraction >= 1) return null;
388	  const windowStart = new Date(now);
389	  windowStart.setHours(hours.start, 0, 0, 0);
390	  const last = lastMovementAt
391	    ? new Date(lastMovementAt).getTime()
392	    : Number.NEGATIVE_INFINITY;
393	  const ref = Math.max(last, windowStart.getTime());
394	  return (now.getTime() - ref) / 3_600_000;
395	}
