  formatCompactBRL,
} from '../model/tvMath';
import { TV_PERIOD_LABEL, formatAgoLabel, formatQty, formatTimeHHMM } from './tvFormat';

/** Borda + glow por estado RAG (sinal lível a 5m — mesma régua da v2). */
const COLUMN_RAG_FRAME: Record<TvRagStatus, string> = {
  ok: 'border border-[#57715B]/10 shadow-[0_8px_32px_rgba(0,0,0,0.06)]',
  amber: 'border-2 border-amber-400/60 shadow-[0_8px_32px_rgba(245,158,11,0.18)]',
  red: 'border-2 border-red-400/70 shadow-[0_8px_32px_rgba(229,72,77,0.15)]',
};

interface TvUnitColumnProps {
  lojaId: number;
  nome: string;
  rag: TvRagStatus;
  /** Hairline dourado de assinatura (fábrica). */
  goldHairline?: boolean;
  testId: string;
  children: ReactNode;
}

/**
 * Chassi da coluna vertical: glass premium + frame RAG + clique/teclado
 * navegando para o drill-down `/tv/loja/:id`.
 */
export function TvUnitColumn({
  lojaId,
  nome,
  rag,
  goldHairline = false,
  testId,
  children,
}: TvUnitColumnProps) {
  const navigate = useNavigate();
  const open = () => navigate(`/tv/loja/${lojaId}`);
  const onKeyDown = (e: KeyboardEvent<HTMLElement>) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      open();
    }
  };

  return (
    <section
      role="link"
      tabIndex={0}
      aria-label={`Abrir detalhes de ${nome}`}
      onClick={open}
      onKeyDown={onKeyDown}
      className={`relative flex cursor-pointer flex-col overflow-hidden rounded-[2rem] bg-white/60 p-3.5 backdrop-blur-xl saturate-150 transition-[border-color,box-shadow,background-color] [transition-duration:300ms] hover:bg-white/80 hover:shadow-[0_12px_40px_rgba(0,0,0,0.10)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/40 motion-reduce:transition-none lg:p-4 ${COLUMN_RAG_FRAME[rag]}`}
      data-testid={testId}
      data-rag={rag}
    >
      {/* Gradiente interno sutil (assinatura glass premium) */}
      <div
        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
        aria-hidden
      />
      {goldHairline && (
        <div className="absolute inset-x-0 top-0 h-0.5 bg-[#C5A065]/60" aria-hidden />
      )}
      <div className="relative z-10 flex h-full min-h-0 flex-col">{children}</div>
    </section>
  );
}

/** Rótulo micro de seção dentro da coluna ("PERDAS · HOJE", "AGORA"…). */
export function TvColumnLabel({ children }: { children: ReactNode }) {
  return (
    <p className="font-momma text-[clamp(0.6875rem,0.75vw,1.375rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
      {children}
    </p>
  );
}

/**
 * Linha de "pulso" da unidade: última bipagem com hora + "há X min".
 * Sem bipagem hoje → texto explícito (nunca campo em branco).
 */
export function TvColumnBipLine({
  ultimaBipagem,
  now,
}: {
  ultimaBipagem: string | null;
  now: Date;
}) {
  const time = formatTimeHHMM(ultimaBipagem);
  const ago = formatAgoLabel(ultimaBipagem, now);
  return (
    <p
      className="mt-0.5 flex items-center gap-1.5 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium leading-tight text-[#7C887E]"
      data-testid="tv-col-bip"
    >
      <ScanLine className="h-[1em] w-[1em] shrink-0" aria-hidden />
      {time ? `bip ${time}${ago ? ` · ${ago}` : ''}` : 'sem bipagem hoje'}
    </p>
  );
}

/** Perdas da unidade no período do filtro global (R$ + nº de itens). */
export function TvColumnPerdas({
  perdas,
  period,
}: {
  perdas: TvPerdasSummary;
  period: TvPeriod;
}) {
  return (
    <div className="mt-3" data-testid="tv-col-perdas">
      <TvColumnLabel>PERDAS · {TV_PERIOD_LABEL[period]}</TvColumnLabel>
      <p className="mt-0.5 font-momma text-[clamp(0.9375rem,1.1vw,2rem)] font-semibold leading-none text-[#2D362E] tabular-nums">
        {formatCompactBRL(perdas.valor)}
        <span className="font-normal text-[#7C887E]">
          {' '}
          · {perdas.itens} {perdas.itens === 1 ? 'item' : 'itens'}
        </span>
      </p>
    </div>
  );
}

/**
 * Estoque crítico NOMEADO (top {@link TV_CRITICAL_TOP_N} por severidade):
 * ⛔ zerado (vermelho) / ⚠ abaixo do mínimo (âmbar) com "X de Y mín".
 * Vazio → "✓ estoque ok" explícito.
 */
export function TvColumnCritical({ items }: { items: TvCriticalItem[] }) {
  const visible = items.slice(0, TV_CRITICAL_TOP_N);
  const overflow = items.length - visible.length;
  return (
    <div className="mt-3 flex min-h-0 flex-1 flex-col" data-testid="tv-col-critical">
      <TvColumnLabel>ESTOQUE CRÍTICO</TvColumnLabel>
      {items.length === 0 ? (
        <p
          className="mt-1 flex items-center gap-1.5 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] font-medium text-emerald-600"
          data-testid="tv-col-critical-empty"
        >
          <CheckCircle2 className="h-[1em] w-[1em] shrink-0" aria-hidden />
          estoque ok
        </p>
      ) : (
        <ul className="mt-1 space-y-1">
          {visible.map((item) => {
            const zerado = item.severity === 'zerado';
            return (
              <li
                key={item.nome}
                className="flex items-center gap-1.5 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] leading-tight"
                data-testid="tv-col-critical-item"
                data-severity={item.severity}
              >
                {zerado ? (
                  <OctagonAlert
                    className="h-[1em] w-[1em] shrink-0 text-red-500"
                    aria-hidden
                  />
                ) : (
                  <TriangleAlert
                    className="h-[1em] w-[1em] shrink-0 text-amber-500"
                    aria-hidden
                  />
                )}
                <span className="min-w-0 flex-1 truncate font-medium text-[#2D362E]">
                  {item.nome}
                </span>
                <span
                  className={`shrink-0 font-medium tabular-nums ${
                    zerado ? 'text-red-600' : 'text-amber-600'
                  }`}
                >
                  {zerado
                    ? '0 un'
                    : `${formatQty(item.quantidade)} de ${formatQty(item.minima)} mín`}
                </span>
              </li>
            );
          })}
          {overflow > 0 && (
            <li
              className="font-momma text-[clamp(0.6875rem,0.75vw,1.375rem)] text-[#7C887E]"
              data-testid="tv-col-critical-overflow"
            >
              + {overflow} {overflow === 1 ? 'item' : 'itens'}
            </li>
          )}
        </ul>
      )}
    </div>
  );
}

/**
 * Mini-feed "AGORA": últimas {@link TV_MINI_FEED_SIZE} movimentações de
 * hoje (HH:MM ↗/↘ qtd× produto). Vazio → texto explícito.
 */
export function TvColumnFeed({ moves }: { moves: TvRecentMove[] }) {
  const visible = moves.slice(0, TV_MINI_FEED_SIZE);
  return (
    <div className="mt-3" data-testid="tv-col-feed">
      <TvColumnLabel>AGORA</TvColumnLabel>
      {visible.length === 0 ? (
        <p
          className="mt-1 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] text-[#7C887E]"
          data-testid="tv-col-feed-empty"
        >
          sem movimentações hoje
        </p>
      ) : (
        <ul className="mt-1 space-y-1">
          {visible.map((m, i) => (
            <li
              key={`${m.timestamp ?? 'sem-ts'}-${m.produtoNome}-${i}`}
              className="flex items-center gap-1.5 font-momma text-[clamp(0.75rem,0.85vw,1.5rem)] leading-tight"
              data-testid="tv-col-feed-item"
            >
              <span className="shrink-0 font-medium text-[#7C887E] tabular-nums">
                {m.hora}
              </span>
              {m.tipo === 'entrada' ? (
                <ArrowUpRight
                  className="h-[1em] w-[1em] shrink-0 text-[#57715B]"
                  aria-hidden
                />
              ) : (
                <ArrowDownRight
                  className="h-[1em] w-[1em] shrink-0 text-[#7C887E]"
                  aria-hidden
                />
              )}
              <span className="min-w-0 flex-1 truncate text-[#2D362E]">
                {formatQty(m.quantidade)}× {m.produtoNome}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/**
 * @module features/tv-dashboard/ui/TvStoreColumn
 *
 * Coluna VERTICAL de loja da v3 (substitui o card horizontal da v2).
 * De cima para baixo: header (nome + chip RAG + fonte) · última bipagem ·
 * vendas de hoje + % vs ontem (pró-rata p/ canal live; Linx com selo
 * honesto "até DD/MM") · perdas do período do filtro global · estoque
 * crítico NOMEADO (top 5) · mini-feed "AGORA". A coluna inteira é clicável
 * e navega para `/tv/loja/:id`.
 */

import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
import { formatCompactBRL, parseBrDateTime, parseIsoDateLocal } from '../model/tvMath';
import { TvDeltaChip, TvSourceChip, TvStateChip } from './TvChips';
import {
  TvColumnBipLine,
  TvColumnCritical,
  TvColumnFeed,
  TvColumnPerdas,
  TvUnitColumn,
} from './TvColumnParts';
import { formatTimeHHMM, formatWeekdayDayMonth } from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvStoreColumnProps {
  store: TvStoreData;
  /** Freshness da fonte de vendas live (chip "ao vivo"/"atrasado"). */
  liveLevel: TvFreshnessLevel;
  /** Período do filtro global (rótulo honesto das perdas). */
  period: TvPeriod;
  now: Date;
}

/** Coluna de loja: cobre canal Degust live e Linx defasado. */
export function TvStoreColumn({ store, liveLevel, period, now }: TvStoreColumnProps) {
  const { vendas, channel } = store;
  const isLive = channel === 'degust-live';
  const valorAnim = useCountUp(vendas?.valor ?? 0);
  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;

  // Caption sob as vendas: honestidade da fonte (live × defasado × sem dado)
  let caption: string;
  if (vendas == null) {
    caption = 'sem dado de venda disponível';
  } else if (isLive) {
    // `ultima_atualizacao` do Degust vem "DD/MM/YYYY HH:mm:ss" — parser
    // dedicado pt-BR (new Date() falha para dia > 12).
    const upd = formatTimeHHMM(parseBrDateTime(vendas.atualizadoEm));
    caption = `hoje${upd ? ` · atualizado ${upd}` : ''}`;
  } else {
    caption = `${refDate ? formatWeekdayDayMonth(refDate) : ''} — último dia com dados`;
  }

  return (
    <TvUnitColumn
      lojaId={store.lojaId}
      nome={store.nome}
      rag={store.rag}
      testId="tv-store-column"
    >
      {/* Header: nome + chips (RAG + fonte) */}
      <div className="flex flex-wrap items-center justify-between gap-x-2 gap-y-1">
        <h2 className="min-w-0 truncate font-momma text-[clamp(0.9375rem,1.05vw,1.875rem)] font-semibold leading-tight text-[#2D362E]">
          {store.nome}
        </h2>
        <div className="flex shrink-0 flex-wrap items-center justify-end gap-1.5">
          <TvStateChip rag={store.rag} />
          <TvSourceChip
            channel={channel}
            liveLevel={liveLevel}
            laggedDate={vendas?.dataReferencia ?? null}
          />
        </div>
      </div>
      <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />

      {/* Vendas de hoje + % vs ontem (principal v3) */}
      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
        <span
          className={`font-momma text-[clamp(1.75rem,1.95vw,3.5rem)] font-bold leading-none tabular-nums ${
            vendas ? 'text-[#2D362E]' : 'text-[#7C887E]'
          }`}
          data-testid="tv-store-sales"
        >
          {vendas ? formatCompactBRL(valorAnim) : '—'}
        </span>
        {store.deltaOntem != null && (
          <TvDeltaChip
            delta={store.deltaOntem}
            label={isLive ? 'ontem' : 'dia ant.'}
            size="card"
          />
        )}
      </div>
      <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium leading-tight text-[#7C887E]">
        {caption}
      </p>

      <TvColumnPerdas perdas={store.perdas} period={period} />
      <TvColumnCritical items={store.criticalItems} />
      <TvColumnFeed moves={store.recentMoves} />
    </TvUnitColumn>
  );
}

/**
 * @module features/tv-dashboard/ui/TvFabricaColumn
 *
 * Coluna VERTICAL da fábrica (v3 — posição 6): mesma anatomia da coluna de
 * loja, com PRODUÇÃO do dia + EXPEDIÇÕES no lugar de vendas. Hairline GOLD
 * de assinatura. Clicável → `/tv/loja/:id` (drill-down da unidade).
 */

import { ArrowDownRight, ArrowUpRight, Factory } from 'lucide-react';
import type { TvFactoryData, TvFreshness, TvPeriod } from '../model/types';
import { parseIsoDateLocal, toIsoDateLocal } from '../model/tvMath';
import { TvSourceChip, TvStateChip } from './TvChips';
import {
  TvColumnBipLine,
  TvColumnCritical,
  TvColumnFeed,
  TvColumnLabel,
  TvColumnPerdas,
  TvUnitColumn,
} from './TvColumnParts';
import { formatInt, formatWeekdayDayMonth } from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvFabricaColumnProps {
  factory: TvFactoryData;
  freshness: TvFreshness;
  /** Período do filtro global (rótulo honesto das perdas). */
  period: TvPeriod;
  now: Date;
}

/** Coluna da fábrica: nunca tem venda — produção/expedições + operação. */
export function TvFabricaColumn({
  factory,
  freshness,
  period,
  now,
}: TvFabricaColumnProps) {
  const producao = factory.producao;
  const unidadesAnim = Math.round(useCountUp(producao?.totalUnidades ?? 0));

  const todayIso = toIsoDateLocal(now);
  const isToday = producao?.dataReferencia === todayIso;
  const refLabel =
    producao && !isToday
      ? formatWeekdayDayMonth(parseIsoDateLocal(producao.dataReferencia))
      : null;

  return (
    <TvUnitColumn
      lojaId={factory.lojaId}
      nome={factory.nome}
      rag={factory.rag}
      goldHairline
      testId="tv-fabrica-column"
    >
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-x-2 gap-y-1">
        <h2 className="flex min-w-0 items-center gap-1.5 truncate font-momma text-[clamp(0.9375rem,1.05vw,1.875rem)] font-semibold leading-tight text-[#2D362E]">
          <Factory className="h-[0.95em] w-[0.95em] shrink-0 text-[#C5A065]" aria-hidden />
          {factory.nome}
        </h2>
        <div className="flex shrink-0 flex-wrap items-center justify-end gap-1.5">
          <TvStateChip rag={factory.rag} />
          <TvSourceChip channel="factory" liveLevel={freshness.estoque.level} />
        </div>
      </div>
      <TvColumnBipLine ultimaBipagem={factory.expedicoes.ultimaBipagem} now={now} />

      {/* Produção (no lugar de vendas) */}
      <div className="mt-2 flex items-end gap-2">
        <span
          className={`font-momma text-[clamp(1.75rem,1.95vw,3.5rem)] font-bold leading-none tabular-nums ${
            producao ? 'text-[#2D362E]' : 'text-[#7C887E]'
          }`}
          data-testid="tv-fabrica-producao"
        >
          {producao ? formatInt(unidadesAnim) : '—'}
        </span>
        {producao && (
          <span className="pb-0.5 font-momma text-[clamp(1rem,1.15vw,2rem)] font-normal leading-none text-[#5F6F63]">
            un
          </span>
        )}
      </div>
      <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium leading-tight text-[#7C887E]">
        {producao
          ? `produzido ${refLabel ? `em ${refLabel}` : 'hoje'}`
          : 'sem produção registrada'}
      </p>

      {/* Expedições de hoje (entradas/saídas da fábrica) */}
      <div className="mt-3" data-testid="tv-fabrica-expedicoes">
        <TvColumnLabel>EXPEDIÇÕES · hoje</TvColumnLabel>
        <p className="mt-0.5 flex items-center gap-1.5 font-momma text-[clamp(0.9375rem,1.1vw,2rem)] font-semibold leading-none text-[#2D362E] tabular-nums">
          <ArrowDownRight className="h-[0.85em] w-[0.85em] shrink-0 text-[#5F6F63]" aria-hidden />
          {formatInt(factory.expedicoes.saidas)}
          <ArrowUpRight
            className="ml-2 h-[0.85em] w-[0.85em] shrink-0 text-[#5F6F63]"
            aria-hidden
          />
          {formatInt(factory.expedicoes.entradas)}
        </p>
      </div>

      <TvColumnPerdas perdas={factory.perdas} period={period} />
      <TvColumnCritical items={factory.criticalItems} />
      <TvColumnFeed moves={factory.recentMoves} />
    </TvUnitColumn>
  );
}

/**
 * @module features/tv-dashboard/ui/TvHero
 *
 * Hero v3 da Torre de Controle: vendas da rede HOJE + % vs ONTEM
 * (comparativo principal; barra de meta pró-rata vira secundária),
 * COMPRAS e PERDAS do período do filtro global, contador de alertas
 * críticos, relógio + freshness e o FILTRO GLOBAL Hoje/Semana/Mês
 * (segmented control glass — muda perdas/compras/comparativos).
 *
 * Linha 1: marca + (freshness · relógio · filtro). Linha 2: métricas.
 * Mobile empilha; lg+ vira a faixa de 4 zonas.
 */

import { ArrowDown, ArrowUp, Check, OctagonAlert, RefreshCw } from 'lucide-react';
import type { TvFreshness, TvNetworkSummary, TvPeriod } from '../model/types';
import { formatCompactBRL } from '../model/tvMath';
import { TvDeltaChip, TvMetaBar } from './TvChips';
import {
  TV_PERIOD_LABEL,
  expectedPctNow,
  formatDeltaPct,
  formatTimeHHMM,
  metaBarColorFromRatio,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvHeroProps {
  network: TvNetworkSummary | null;
  freshness: TvFreshness;
  now: Date;
  /** Período do filtro global (controlado pela página). */
  period: TvPeriod;
  onPeriodChange: (period: TvPeriod) => void;
}

const PERIOD_OPTIONS: ReadonlyArray<{ value: TvPeriod; label: string }> = [
  { value: 'today', label: 'Hoje' },
  { value: 'week', label: 'Semana' },
  { value: 'month', label: 'Mês' },
];

/** Segmented control glass do filtro global (Hoje/Semana/Mês). */
function TvPeriodFilter({
  period,
  onPeriodChange,
}: {
  period: TvPeriod;
  onPeriodChange: (period: TvPeriod) => void;
}) {
  return (
    <div
      className="inline-flex shrink-0 items-center rounded-full border border-[#57715B]/15 bg-white/60 p-1 backdrop-blur-md"
      role="group"
      aria-label="Período de perdas, compras e comparativos"
      data-testid="tv-period-filter"
    >
      {PERIOD_OPTIONS.map((opt) => {
        const active = opt.value === period;
        return (
          <button
            key={opt.value}
            type="button"
            aria-pressed={active}
            onClick={() => onPeriodChange(opt.value)}
            className={`rounded-full px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium leading-none transition-colors motion-reduce:transition-none lg:px-4 lg:py-1.5 ${
              active
                ? 'bg-[#57715B] text-white shadow-sm'
                : 'text-[#5F6F63] hover:bg-[#57715B]/10'
            }`}
          >
            {opt.label}
          </button>
        );
      })}
    </div>
  );
}

/**
 * Linha de delta vs período anterior (compras/perdas). Neutra por padrão;
 * âmbar SÓ no desvio ruim (`amberWhenUp`: perdas subindo). Sem base → texto
 * honesto "sem base anterior".
 */
function TvHeroDeltaLine({
  deltaPct,
  amberWhenUp = false,
}: {
  deltaPct: number | null;
  amberWhenUp?: boolean;
}) {
  if (deltaPct == null) {
    return (
      <span className="font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] text-[#7C887E]">
        sem base anterior
      </span>
    );
  }
  const isAmber = amberWhenUp && deltaPct > 0;
  const Icon = deltaPct < 0 ? ArrowDown : ArrowUp;
  return (
    <span
      className={`inline-flex items-center gap-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium tabular-nums ${
        isAmber ? 'text-amber-600' : 'text-[#7C887E]'
      }`}
    >
      <Icon className="h-[1em] w-[1em] shrink-0" aria-hidden />
      {formatDeltaPct(deltaPct)} vs anterior
    </span>
  );
}

/** Hero da rede (v3): marca/relógio/filtro + faixa de métricas. */
export function TvHero({ network, freshness, now, period, onPeriodChange }: TvHeroProps) {
  const vendas = useCountUp(network?.vendasHoje ?? 0);
  const hasData = network != null;
  const periodLabel = TV_PERIOD_LABEL[period];

  // Barra de meta (SECUNDÁRIA na v3): preenchimento = % do dia COMPLETO;
  // tick dourado = esperado agora (pró-rata).
  const fullDayPct =
    network && network.metaDia != null && network.metaDia > 0
      ? (network.vendasHoje / network.metaDia) * 100
      : null;
  const expected = expectedPctNow(now);
  const ratio = network?.pctMetaProRata != null ? network.pctMetaProRata / 100 : null;
  const barColor = metaBarColorFromRatio(ratio, now);

  const alertas = network?.alertasCriticos ?? 0;
  const alertasAnim = Math.round(useCountUp(alertas));

  const liveFresh = freshness.vendasLive.level === 'fresh';
  const liveTime = formatTimeHHMM(freshness.vendasLive.updatedAt);

  return (
    <header
      className="flex flex-col gap-4 border-b border-[#C5A065]/25 pb-4 lg:gap-5"
      data-testid="tv-hero"
    >
      {/* Linha 1 — marca + relógio/freshness/filtro global */}
      <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
        <div className="flex min-w-0 items-baseline gap-3">
          <span className="font-momma text-[clamp(0.875rem,1.05vw,1.875rem)] font-bold uppercase tracking-[0.3em] text-[#C5A065]">
            MOMMA
          </span>
          <span className="truncate font-serif text-[clamp(1rem,1.35vw,2.5rem)] font-semibold tracking-tight text-[#2D362E]">
            Torre de Controle
          </span>
        </div>
        <div className="flex flex-wrap items-center gap-x-4 gap-y-2 lg:gap-x-5">
          {liveFresh ? (
            <span className="inline-flex items-center gap-2 rounded-full bg-emerald-50 px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium text-emerald-600">
              <Check className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
              ao vivo{liveTime ? ` · ${liveTime}` : ''}
            </span>
          ) : (
            <span className="inline-flex items-center gap-2 rounded-full border border-amber-400/40 bg-amber-50 px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium text-amber-600">
              <RefreshCw className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
              atrasado{liveTime ? ` · último ${liveTime}` : ''}
            </span>
          )}
          <span className="font-momma text-[clamp(1.25rem,2vw,3.75rem)] font-light leading-none text-[#2D362E] tabular-nums">
            {formatTimeHHMM(now)}
          </span>
          <TvPeriodFilter period={period} onPeriodChange={onPeriodChange} />
        </div>
      </div>

      {/* Linha 2 — métricas: vendas | compras | perdas | alertas */}
      <div className="grid grid-cols-2 items-end gap-x-4 gap-y-4 lg:grid-cols-[1.7fr_1fr_1fr_0.9fr] lg:gap-8">
        {/* Zona 1 — vendas da rede hoje + % vs ontem (principal) */}
        <div className="col-span-2 min-w-0 lg:col-span-1">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            REDE · VENDAS HOJE
          </span>
          <div className="mt-1 flex flex-wrap items-end gap-x-4 gap-y-2">
            <span
              className="font-momma text-[clamp(2.25rem,4vw,7.5rem)] font-bold leading-none text-[#2D362E] tabular-nums"
              data-testid="tv-hero-sales"
            >
              {hasData ? formatCompactBRL(vendas) : '—'}
            </span>
            {network?.deltaOntem != null && (
              <span className="pb-1">
                <TvDeltaChip delta={network.deltaOntem} label="ontem" size="hero" />
              </span>
            )}
          </div>
          {/* Meta pró-rata — secundária desde a v3 */}
          <div className="mt-2 max-w-[36rem]">
            <TvMetaBar
              fillPct={fullDayPct}
              expectedPct={fullDayPct != null ? expected : null}
              color={barColor}
              size="card"
            />
            <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] leading-tight">
              {fullDayPct != null ? (
                <>
                  <span className="font-medium text-[#5F6F63]">
                    {Math.round(fullDayPct)}% da meta
                  </span>
                  <span className="text-[#7C887E]"> · esperado {expected}%</span>
                </>
              ) : (
                <span className="text-[#7C887E]">sem meta cadastrada</span>
              )}
            </p>
          </div>
        </div>

        {/* Zona 2 — compras do período */}
        <div className="min-w-0">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            COMPRAS · {periodLabel}
          </span>
          <p
            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
            data-testid="tv-hero-compras"
          >
            {hasData ? formatCompactBRL(network.compras.valor) : '—'}
          </p>
          <p className="mt-1">
            <TvHeroDeltaLine deltaPct={network?.compras.deltaPct ?? null} />
          </p>
        </div>

        {/* Zona 3 — perdas do período (R$ + itens; subir é desvio → âmbar) */}
        <div className="min-w-0">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            PERDAS · {periodLabel}
          </span>
          <p
            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
            data-testid="tv-hero-perdas"
          >
            {hasData ? formatCompactBRL(network.perdas.valor) : '—'}
            {hasData && (
              <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
                {' '}
                · {network.perdas.itens} {network.perdas.itens === 1 ? 'item' : 'itens'}
              </span>
            )}
          </p>
          <p className="mt-1">
            <TvHeroDeltaLine deltaPct={network?.perdas.deltaPct ?? null} amberWhenUp />
          </p>
        </div>

        {/* Zona 4 — alertas críticos */}
        <div className="min-w-0">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            ALERTAS CRÍTICOS
          </span>
          <div className="mt-1 flex items-center gap-2 lg:gap-3" data-testid="tv-hero-alerts">
            {alertas === 0 ? (
              <>
                <Check
                  className="h-[clamp(1.25rem,1.8vw,3.25rem)] w-[clamp(1.25rem,1.8vw,3.25rem)] shrink-0 text-emerald-500"
                  aria-hidden
                />
                <span className="font-momma text-[clamp(1.75rem,2.8vw,5rem)] font-bold leading-none text-emerald-600 tabular-nums">
                  0
                </span>
              </>
            ) : (
              <>
                <OctagonAlert
                  className="h-[clamp(1.5rem,2vw,3.75rem)] w-[clamp(1.5rem,2vw,3.75rem)] shrink-0 text-red-500"
                  aria-hidden
                />
                <span className="font-momma text-[clamp(1.75rem,2.8vw,5rem)] font-bold leading-none text-red-600 tabular-nums">
                  {alertasAnim}
                </span>
              </>
            )}
          </div>
        </div>
      </div>
    </header>
  );
}

