/**
 * @module features/tv-dashboard/ui/TvStoreDetail.page
 *
 * Drill-down `/tv/loja/:id` (v3): visão completa de UMA unidade dentro do
 * layout do app (DashboardLayout aplicado na rota, como `/tv/metas`).
 *
 * - Filtro de data PRÓPRIO: presets Hoje / 7 dias / Mês + intervalo custom
 *   (Calendar shadcn, padrão do projeto);
 * - KPIs glass (vendas, perdas, compras, movimentações) com delta vs
 *   período ANTERIOR de mesma duração;
 * - Listas: perdas detalhadas, NFs de compra, estoque crítico COMPLETO
 *   (estado ATUAL) e feed de movimentações (até 50, mais recente 1º);
 * - Estados vazios explícitos em toda lista; skeleton no loading; erro com
 *   mensagem. Fábrica não vende → KPI de vendas sai (nunca "R$ 0" falso).
 */

import { useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import type { DateRange } from 'react-day-picker';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import {
  ArrowDown,
  ArrowDownRight,
  ArrowLeft,
  ArrowUp,
  ArrowUpRight,
  Banknote,
  CalendarIcon,
  CheckCircle2,
  Factory,
  OctagonAlert,
  PackageX,
  Receipt,
  Repeat,
  Store,
  TriangleAlert,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Calendar } from '@/shared/ui/calendar';
import { GlassCard } from '@/shared/ui/glass-card';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import { Skeleton } from '@/shared/ui/skeleton';
import { cn } from '@/shared/lib/utils';
import type { TvDateRange, TvRagStatus } from '../model/types';
import {
  addDays,
  formatCompactBRL,
  parseIsoDateLocal,
  periodRange,
  toIsoDateLocal,
} from '../model/tvMath';
import { useTvStoreDetail } from '../model/useTvStoreDetail';
import { useTvRealtime } from '../model/useTvRealtime';
import { TvStateChip } from './TvChips';
import { formatDeltaPct, formatInt, formatQty } from './tvFormat';

// ─────────────────────────────────────────────────────────────────────────────
// Filtro de data (presets + custom)
// ─────────────────────────────────────────────────────────────────────────────

type DetailPreset = 'today' | '7d' | 'month' | 'custom';

const PRESET_OPTIONS: ReadonlyArray<{ value: Exclude<DetailPreset, 'custom'>; label: string }> = [
  { value: 'today', label: 'Hoje' },
  { value: '7d', label: '7 dias' },
  { value: 'month', label: 'Mês' },
];

/** Range FECHADO [from, to] (dias locais) para o preset escolhido. */
function presetToRange(preset: Exclude<DetailPreset, 'custom'>, now: Date): TvDateRange {
  if (preset === 'today') {
    const today = toIsoDateLocal(now);
    return { from: today, to: today };
  }
  if (preset === '7d') {
    return { from: toIsoDateLocal(addDays(now, -6)), to: toIsoDateLocal(now) };
  }
  return periodRange('month', now);
}

/** "01/06 – 05/06/2026" para o range corrente (rótulo honesto do filtro). */
function rangeLabel(range: TvDateRange): string {
  const from = parseIsoDateLocal(range.from);
  const to = parseIsoDateLocal(range.to);
  if (range.from === range.to) return format(to, 'dd/MM/yyyy', { locale: ptBR });
  return `${format(from, 'dd/MM', { locale: ptBR })} – ${format(to, 'dd/MM/yyyy', { locale: ptBR })}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers de apresentação
// ─────────────────────────────────────────────────────────────────────────────

/** R$ completo pt-BR para linhas de lista ("R$ 1.234,56"). */
function formatFullBRL(value: number): string {
  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

/** "dd/MM HH:mm" de um timestamp ISO, ou "—" sem dado. */
function formatTimestamp(iso: string | null): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  return format(d, 'dd/MM HH:mm', { locale: ptBR });
}

/** "dd/MM/yyyy" de uma data-dia local (YYYY-MM-DD). */
function formatDay(isoDate: string): string {
  return format(parseIsoDateLocal(isoDate), 'dd/MM/yyyy', { locale: ptBR });
}

/**
 * Delta % vs período anterior dos KPIs. Neutro por padrão; âmbar SÓ em
 * desvio (perdas subindo / vendas caindo forte). Sem base → texto honesto.
 */
function DetailDelta({
  deltaPct,
  tone = 'neutral',
}: {
  deltaPct: number | null;
  tone?: 'neutral' | 'up-is-bad' | 'down-is-bad';
}) {
  if (deltaPct == null) {
    return <span className="text-xs text-muted-foreground">sem base anterior</span>;
  }
  const isAmber =
    (tone === 'up-is-bad' && deltaPct > 0) ||
    (tone === 'down-is-bad' && deltaPct <= -15);
  const Icon = deltaPct < 0 ? ArrowDown : ArrowUp;
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium tabular-nums',
        isAmber
          ? 'bg-amber-50 text-amber-600 dark:bg-amber-900/20'
          : 'bg-[#57715B]/8 text-[#5F6F63] dark:text-[#8FAE94]',
      )}
    >
      <Icon className="h-3 w-3 shrink-0" aria-hidden />
      {formatDeltaPct(deltaPct)} vs anterior
    </span>
  );
}

/** KPI card glass (padrão do design system, com watermark de ícone). */
function KpiCard({
  icon: Icon,
  label,
  value,
  sub,
  delta,
  testId,
}: {
  icon: typeof Banknote;
  label: string;
  value: string;
  sub?: string;
  delta: React.ReactNode;
  testId: string;
}) {
  return (
    <div
      className="group relative overflow-hidden rounded-[2rem] border border-[#57715B]/10 bg-white/60 p-5 shadow-sm backdrop-blur-md transition-shadow hover:shadow-md dark:bg-[#1A1A1A]/60"
      data-testid={testId}
    >
      <Icon
        className="absolute right-3 top-3 h-10 w-10 text-[#57715B] opacity-10 transition-opacity group-hover:opacity-20"
        aria-hidden
      />
      <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
        {label}
      </p>
      <p className="mt-1 text-2xl font-bold text-[#2D362E] tabular-nums dark:text-[#E6DCCF]">
        {value}
        {sub && (
          <span className="ml-1.5 text-sm font-normal text-muted-foreground">{sub}</span>
        )}
      </p>
      <p className="mt-2">{delta}</p>
    </div>
  );
}

/** Card de lista glass com header + contagem e corpo scrollável. */
function ListCard({
  title,
  count,
  children,
  testId,
}: {
  title: string;
  count?: number;
  children: React.ReactNode;
  testId: string;
}) {
  return (
    <GlassCard variant="premium" className="p-5" data-testid={testId}>
      <div className="flex items-center justify-between">
        <h2 className="text-xs font-semibold uppercase tracking-wider text-[#57715B] dark:text-[#8FAE94]">
          {title}
        </h2>
        {count != null && count > 0 && (
          <span className="text-xs font-medium text-muted-foreground tabular-nums">
            {count}
          </span>
        )}
      </div>
      <div className="mt-3">{children}</div>
    </GlassCard>
  );
}

/** Estado vazio explícito de lista (nunca área em branco). */
function EmptyState({
  message,
  ok = false,
  testId,
}: {
  message: string;
  ok?: boolean;
  testId: string;
}) {
  return (
    <p
      className={cn(
        'flex items-center gap-2 py-6 text-sm justify-center',
        ok ? 'text-emerald-600' : 'text-muted-foreground',
      )}
      data-testid={testId}
    >
      {ok && <CheckCircle2 className="h-4 w-4 shrink-0" aria-hidden />}
      {message}
    </p>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Página
// ─────────────────────────────────────────────────────────────────────────────

/** Drill-down de uma unidade (admin only — rota protegida em App.tsx). */
export default function TvStoreDetailPage() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const lojaId = id != null && /^\d+$/.test(id) ? Number(id) : null;

  const [preset, setPreset] = useState<DetailPreset>('today');
  const [customRange, setCustomRange] = useState<DateRange | undefined>();

  const range = useMemo<TvDateRange>(() => {
    if (preset === 'custom' && customRange?.from) {
      const from = toIsoDateLocal(customRange.from);
      const to = toIsoDateLocal(customRange.to ?? customRange.from);
      // Calendar permite seleção "de trás pra frente" — normaliza
      return from <= to ? { from, to } : { from: to, to: from };
    }
    return presetToRange(preset === 'custom' ? 'today' : preset, new Date());
  }, [preset, customRange]);

  const data = useTvStoreDetail(lojaId, range);
  useTvRealtime();

  const isFactory = data.channel === 'factory';
  const notFound = lojaId == null || (!data.isLoading && data.nome == null);

  // RAG do header derivado do estoque crítico ATUAL (mesma régua dura do
  // painel: zerado = vermelho; abaixo do mínimo = âmbar). Sinais de venda/
  // movimentação são do painel ao vivo — não se aplicam a range histórico.
  const rag: TvRagStatus = useMemo(() => {
    if (data.criticalItems.some((i) => i.severity === 'zerado')) return 'red';
    if (data.criticalItems.length > 0) return 'amber';
    return 'ok';
  }, [data.criticalItems]);

  // ── Loja inexistente / id inválido ──
  if (notFound) {
    return (
      <div className="space-y-6 p-4 md:p-6" data-testid="tv-store-detail-page">
        <GlassCard variant="premium" className="p-8 text-center">
          <p className="text-lg font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
            Loja não encontrada
          </p>
          <p className="mt-1 text-sm text-muted-foreground">
            O endereço aponta para uma unidade que não existe ou foi desativada.
          </p>
          <Button
            onClick={() => navigate('/tv')}
            className="mt-4 bg-[#57715B] text-white hover:bg-[#465b49]"
          >
            <ArrowLeft className="mr-2 h-4 w-4" />
            Voltar para a Torre de Controle
          </Button>
        </GlassCard>
      </div>
    );
  }

  const HeaderIcon = isFactory ? Factory : Store;

  return (
    <div className="space-y-6 p-4 md:p-6" data-testid="tv-store-detail-page">
      {/* Header canônico: voltar + nome + chip RAG */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex min-w-0 items-center gap-3">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate('/tv')}
            data-mia-action="voltar-painel-tv"
            aria-label="Voltar para a Torre de Controle"
            className="rounded-full text-[#57715B] hover:bg-[#57715B]/10 dark:text-[#8FAE94]"
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-[#57715B]/10">
            <HeaderIcon className="h-6 w-6 text-[#57715B] dark:text-[#8FAE94]" />
          </div>
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              {data.nome ? (
                <h1 className="truncate font-serif text-2xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF]">
                  {data.nome}
                </h1>
              ) : (
                <Skeleton className="h-8 w-48" />
              )}
              <TvStateChip rag={rag} />
            </div>
            <p className="text-xs font-medium uppercase tracking-widest text-muted-foreground">
              Torre de Controle · visão da unidade
            </p>
          </div>
        </div>

        {/* Filtro de data próprio: presets + intervalo custom */}
        <div
          className="flex flex-wrap items-center gap-2"
          data-testid="tv-detail-range-filter"
        >
          <div className="inline-flex items-center rounded-full border border-[#57715B]/15 bg-white/60 p-1 backdrop-blur-md dark:bg-black/20">
            {PRESET_OPTIONS.map((opt) => {
              const active = preset === opt.value;
              return (
                <button
                  key={opt.value}
                  type="button"
                  aria-pressed={active}
                  onClick={() => setPreset(opt.value)}
                  className={cn(
                    'rounded-full px-3 py-1.5 text-xs font-medium leading-none transition-colors',
                    active
                      ? 'bg-[#57715B] text-white shadow-sm'
                      : 'text-[#5F6F63] hover:bg-[#57715B]/10 dark:text-[#8FAE94]',
                  )}
                >
                  {opt.label}
                </button>
              );
            })}
          </div>
          <Popover>
            <PopoverTrigger asChild>
              <Button
                variant="outline"
                className={cn(
                  'h-8 justify-start rounded-full border-[#57715B]/15 bg-white/60 text-left text-xs font-normal backdrop-blur-md hover:bg-white/80 dark:bg-black/20',
                  preset === 'custom' && 'border-[#57715B]/40 text-[#57715B] dark:text-[#8FAE94]',
                )}
              >
                <CalendarIcon className="mr-2 h-3.5 w-3.5" aria-hidden />
                {preset === 'custom' ? rangeLabel(range) : 'Intervalo'}
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-auto rounded-xl p-0" align="end">
              <Calendar
                initialFocus
                mode="range"
                defaultMonth={customRange?.from}
                selected={customRange}
                onSelect={(next) => {
                  setCustomRange(next);
                  if (next?.from) setPreset('custom');
                }}
                numberOfMonths={2}
                locale={ptBR}
                disabled={{ after: new Date() }}
                className="p-3"
              />
            </PopoverContent>
          </Popover>
          <span className="text-xs text-muted-foreground tabular-nums">
            {rangeLabel(range)}
          </span>
        </div>
      </div>

      {data.isError ? (
        <GlassCard variant="premium" className="p-8 text-center">
          <p className="text-lg font-semibold text-red-600">
            Não foi possível carregar os dados da unidade
          </p>
          <p className="mt-1 text-sm text-muted-foreground">
            Verifique a conexão e tente novamente em instantes.
          </p>
        </GlassCard>
      ) : data.isLoading ? (
        <div className="space-y-6" data-testid="tv-detail-skeleton">
          <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
            {Array.from({ length: 4 }, (_, i) => (
              <Skeleton key={i} className="h-32 rounded-[2rem]" />
            ))}
          </div>
          <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
            {Array.from({ length: 4 }, (_, i) => (
              <Skeleton key={i} className="h-64 rounded-[2rem]" />
            ))}
          </div>
        </div>
      ) : (
        <>
          {/* KPIs do período (vs período anterior de mesma duração) */}
          <div
            className={cn(
              'grid grid-cols-2 gap-4',
              isFactory ? 'lg:grid-cols-3' : 'lg:grid-cols-4',
            )}
          >
            {!isFactory && (
              <KpiCard
                icon={Banknote}
                label="Vendas"
                value={formatCompactBRL(data.vendas.valor)}
                sub={data.channel === 'linx-lagged' ? 'fonte Linx (defasada)' : undefined}
                delta={<DetailDelta deltaPct={data.vendas.deltaPct} tone="down-is-bad" />}
                testId="tv-detail-kpi-vendas"
              />
            )}
            <KpiCard
              icon={PackageX}
              label="Perdas"
              value={formatCompactBRL(data.perdas.valor)}
              sub={`${data.perdas.itens} ${data.perdas.itens === 1 ? 'item' : 'itens'}`}
              delta={<DetailDelta deltaPct={data.perdas.deltaPct} tone="up-is-bad" />}
              testId="tv-detail-kpi-perdas"
            />
            <KpiCard
              icon={Receipt}
              label="Compras"
              value={formatCompactBRL(data.compras.valor)}
              sub={`${data.notasList.length} ${data.notasList.length === 1 ? 'NF' : 'NFs'}`}
              delta={<DetailDelta deltaPct={data.compras.deltaPct} />}
              testId="tv-detail-kpi-compras"
            />
            <KpiCard
              icon={Repeat}
              label="Movimentações"
              value={formatInt(data.movimentos.total)}
              sub={`↑ ${formatInt(data.movimentos.entradas)} · ↓ ${formatInt(data.movimentos.saidas)}`}
              delta={<DetailDelta deltaPct={data.movimentos.deltaPct} />}
              testId="tv-detail-kpi-movimentos"
            />
          </div>

          {/* Listas: perdas + compras */}
          <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
            <ListCard
              title="Perdas no período"
              count={data.perdasList.length}
              testId="tv-detail-perdas-list"
            >
              {data.perdasList.length === 0 ? (
                <EmptyState
                  message="Nenhuma perda registrada no período"
                  ok
                  testId="tv-detail-perdas-empty"
                />
              ) : (
                <ul className="max-h-[24rem] divide-y divide-[#57715B]/5 overflow-y-auto">
                  {data.perdasList.map((p) => (
                    <li
                      key={p.id}
                      className="flex items-center gap-3 py-2.5"
                      data-testid="tv-detail-perda-row"
                    >
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF]">
                          {p.produtoNome}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          {formatQty(p.quantidade)}
                          {p.unidade ? ` ${p.unidade}` : ''} · {p.motivo} ·{' '}
                          {formatTimestamp(p.data)}
                        </p>
                      </div>
                      <span className="shrink-0 text-sm font-semibold text-[#2D362E] tabular-nums dark:text-[#E6DCCF]">
                        {formatFullBRL(p.valor)}
                      </span>
                    </li>
                  ))}
                </ul>
              )}
            </ListCard>

            <ListCard
              title="Compras (NFs) no período"
              count={data.notasList.length}
              testId="tv-detail-notas-list"
            >
              {data.notasList.length === 0 ? (
                <EmptyState
                  message="Nenhuma nota fiscal de compra no período"
                  testId="tv-detail-notas-empty"
                />
              ) : (
                <ul className="max-h-[24rem] divide-y divide-[#57715B]/5 overflow-y-auto">
                  {data.notasList.map((n) => (
                    <li
                      key={n.id}
                      className="flex items-center gap-3 py-2.5"
                      data-testid="tv-detail-nota-row"
                    >
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF]">
                          {n.fornecedor}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          NF {n.numero} · {formatDay(n.dataNota)}
                        </p>
                      </div>
                      <span className="shrink-0 text-sm font-semibold text-[#2D362E] tabular-nums dark:text-[#E6DCCF]">
                        {formatFullBRL(n.valor)}
                      </span>
                    </li>
                  ))}
                </ul>
              )}
            </ListCard>
          </div>

          {/* Listas: estoque crítico (estado ATUAL) + feed de movimentações */}
          <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
            <ListCard
              title="Estoque crítico (agora)"
              count={data.criticalItems.length}
              testId="tv-detail-critical-list"
            >
              {data.criticalItems.length === 0 ? (
                <EmptyState
                  message="Estoque ok — nenhum item crítico"
                  ok
                  testId="tv-detail-critical-empty"
                />
              ) : (
                <ul className="max-h-[24rem] divide-y divide-[#57715B]/5 overflow-y-auto">
                  {data.criticalItems.map((item) => {
                    const zerado = item.severity === 'zerado';
                    return (
                      <li
                        key={item.nome}
                        className="flex items-center gap-2.5 py-2.5"
                        data-testid="tv-detail-critical-row"
                        data-severity={item.severity}
                      >
                        {zerado ? (
                          <OctagonAlert
                            className="h-4 w-4 shrink-0 text-red-500"
                            aria-hidden
                          />
                        ) : (
                          <TriangleAlert
                            className="h-4 w-4 shrink-0 text-amber-500"
                            aria-hidden
                          />
                        )}
                        <span className="min-w-0 flex-1 truncate text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF]">
                          {item.nome}
                        </span>
                        <span
                          className={cn(
                            'shrink-0 text-sm font-medium tabular-nums',
                            zerado ? 'text-red-600' : 'text-amber-600',
                          )}
                        >
                          {zerado
                            ? '0 un'
                            : `${formatQty(item.quantidade)} de ${formatQty(item.minima)} mín`}
                        </span>
                      </li>
                    );
                  })}
                </ul>
              )}
            </ListCard>

            <ListCard
              title={`Movimentações no período${data.feed.length >= 50 ? ' · últimas 50' : ''}`}
              count={data.feed.length}
              testId="tv-detail-feed-list"
            >
              {data.feed.length === 0 ? (
                <EmptyState
                  message="Sem movimentações no período"
                  testId="tv-detail-feed-empty"
                />
              ) : (
                <ul className="max-h-[24rem] divide-y divide-[#57715B]/5 overflow-y-auto">
                  {data.feed.map((m, i) => (
                    <li
                      key={`${m.timestamp ?? 'sem-ts'}-${i}`}
                      className="flex items-center gap-2.5 py-2"
                      data-testid="tv-detail-feed-row"
                    >
                      <span className="shrink-0 text-xs font-medium text-muted-foreground tabular-nums">
                        {formatTimestamp(m.timestamp)}
                      </span>
                      {m.tipo === 'entrada' ? (
                        <ArrowUpRight
                          className="h-4 w-4 shrink-0 text-[#57715B] dark:text-[#8FAE94]"
                          aria-hidden
                        />
                      ) : (
                        <ArrowDownRight
                          className="h-4 w-4 shrink-0 text-muted-foreground"
                          aria-hidden
                        />
                      )}
                      <span className="min-w-0 flex-1 truncate text-sm text-[#2D362E] dark:text-[#E6DCCF]">
                        {formatQty(m.quantidade)}× {m.produtoNome}
                      </span>
                    </li>
                  ))}
                </ul>
              )}
            </ListCard>
          </div>
        </>
      )}
    </div>
  );
}

