import { fireEvent, render, screen } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import { TvStoreColumn } from './TvStoreColumn';
import type { TvStoreData } from '../model/types';

// qui 04/06/2026, 14:30 — dentro da janela comercial
const NOW = new Date(2026, 5, 4, 14, 30);

const baseStore: TvStoreData = {
  lojaId: 5,
  nome: 'Momma Águas Claras',
  channel: 'degust-live',
  vendas: {
    valor: 8400,
    cupons: 184,
    ticketMedio: 38.5,
    dataReferencia: '2026-06-04',
    isLive: true,
    caixaAberto: true,
    atualizadoEm: '04/06/2026 14:28:35',
  },
  metaDia: 10_000,
  pctMeta: 120,
  deltaSemana: 6,
  deltaOntem: 4,
  estoque: { zerados: 0, abaixoMinimo: 0 },
  movimentacao: {
    entradas: 12,
    saidas: 8,
    ultimaBipagem: new Date(2026, 5, 4, 14, 21).toISOString(),
  },
  perdas: { valor: 120, itens: 3, deltaPct: null },
  compras: { valor: 0, deltaPct: null },
  criticalItems: [],
  recentMoves: [],
  rag: 'ok',
  ragReasons: [],
};

function renderColumn(store: TvStoreData) {
  return render(
    <MemoryRouter initialEntries={['/tv']}>
      <Routes>
        <Route
          path="/tv"
          element={<TvStoreColumn store={store} liveLevel="fresh" period="today" now={NOW} />}
        />
        <Route path="/tv/loja/:id" element={<div>detalhe-da-loja</div>} />
      </Routes>
    </MemoryRouter>,
  );
}

describe('TvStoreColumn — estados RAG', () => {
  it('NEUTRO: sem chip de estado, com chip "ao vivo" e vendas + delta vs ontem', () => {
    renderColumn(baseStore);
    const col = screen.getByTestId('tv-store-column');
    expect(col).toHaveAttribute('data-rag', 'ok');
    expect(screen.queryByText('ATENÇÃO')).not.toBeInTheDocument();
    expect(screen.queryByText('CRÍTICO')).not.toBeInTheDocument();
    expect(screen.getByTestId('tv-source-chip-live')).toBeInTheDocument();
    expect(screen.getByText('R$ 8,4k')).toBeInTheDocument();
    expect(screen.getByTestId('tv-delta-chip')).toHaveTextContent('4% vs ontem');
    // pulso: última bipagem com hora
    expect(screen.getByTestId('tv-col-bip')).toHaveTextContent('bip 14:21');
  });

  it('ÂMBAR: chip ATENÇÃO + frame âmbar', () => {
    renderColumn({
      ...baseStore,
      rag: 'amber',
      ragReasons: ['3 itens abaixo do mínimo'],
    });
    expect(screen.getByTestId('tv-store-column')).toHaveAttribute('data-rag', 'amber');
    expect(screen.getByText('ATENÇÃO')).toBeInTheDocument();
  });

  it('VERMELHO: chip CRÍTICO + frame vermelho', () => {
    renderColumn({
      ...baseStore,
      rag: 'red',
      ragReasons: ['2 itens zerados em alerta'],
    });
    expect(screen.getByTestId('tv-store-column')).toHaveAttribute('data-rag', 'red');
    expect(screen.getByText('CRÍTICO')).toBeInTheDocument();
  });
});

describe('TvStoreColumn — estoque crítico nomeado', () => {
  it('lista zerados (⛔ 0 un) antes de abaixo do mínimo (⚠ X de Y mín) + overflow', () => {
    renderColumn({
      ...baseStore,
      criticalItems: [
        { nome: 'Brownie', quantidade: 0, minima: 5, severity: 'zerado' },
        { nome: 'Cookie', quantidade: 2, minima: 10, severity: 'abaixo-minimo' },
        { nome: 'Naked', quantidade: 3, minima: 6, severity: 'abaixo-minimo' },
        { nome: 'Cuba', quantidade: 4, minima: 8, severity: 'abaixo-minimo' },
        { nome: 'Disco', quantidade: 1, minima: 4, severity: 'abaixo-minimo' },
        { nome: 'Vulcão', quantidade: 2, minima: 4, severity: 'abaixo-minimo' },
      ],
    });
    const rows = screen.getAllByTestId('tv-col-critical-item');
    // top 5 com severidade do dado (zerado primeiro — ordem vem do model)
    expect(rows).toHaveLength(5);
    expect(rows[0]).toHaveAttribute('data-severity', 'zerado');
    expect(rows[0]).toHaveTextContent('Brownie');
    expect(rows[0]).toHaveTextContent('0 un');
    expect(rows[1]).toHaveTextContent('Cookie');
    expect(rows[1]).toHaveTextContent('2 de 10 mín');
    expect(screen.getByTestId('tv-col-critical-overflow')).toHaveTextContent('+ 1 item');
    expect(screen.queryByTestId('tv-col-critical-empty')).not.toBeInTheDocument();
  });

  it('vazio: confirma explicitamente "estoque ok"', () => {
    renderColumn(baseStore);
    expect(screen.getByTestId('tv-col-critical-empty')).toHaveTextContent('estoque ok');
  });
});

describe('TvStoreColumn — perdas do período + mini-feed AGORA', () => {
  it('mostra perdas com rótulo do período e R$ · N itens', () => {
    renderColumn(baseStore);
    const perdas = screen.getByTestId('tv-col-perdas');
    expect(perdas).toHaveTextContent('PERDAS · hoje');
    expect(perdas).toHaveTextContent('R$ 120');
    expect(perdas).toHaveTextContent('3 itens');
  });

  it('feed mostra hora + qtd× produto; vazio é explícito', () => {
    renderColumn({
      ...baseStore,
      recentMoves: [
        {
          hora: '14:21',
          timestamp: new Date(2026, 5, 4, 14, 21).toISOString(),
          tipo: 'saida',
          produtoNome: 'Brownie Tradicional',
          quantidade: 12,
        },
      ],
    });
    const rows = screen.getAllByTestId('tv-col-feed-item');
    expect(rows).toHaveLength(1);
    expect(rows[0]).toHaveTextContent('14:21');
    expect(rows[0]).toHaveTextContent('12× Brownie Tradicional');
  });

  it('feed vazio: "sem movimentações hoje"', () => {
    renderColumn(baseStore);
    expect(screen.getByTestId('tv-col-feed-empty')).toHaveTextContent(
      'sem movimentações hoje',
    );
  });
});

describe('TvStoreColumn — navegação para o drill-down', () => {
  it('clique na coluna navega para /tv/loja/:id', () => {
    renderColumn(baseStore);
    fireEvent.click(screen.getByTestId('tv-store-column'));
    expect(screen.getByText('detalhe-da-loja')).toBeInTheDocument();
  });

  it('é acessível: role link com Enter navegando', () => {
    renderColumn(baseStore);
    const col = screen.getByRole('link', {
      name: 'Abrir detalhes de Momma Águas Claras',
    });
    fireEvent.keyDown(col, { key: 'Enter' });
    expect(screen.getByText('detalhe-da-loja')).toBeInTheDocument();
  });
});

describe('TvStoreColumn — canal Linx defasado', () => {
  it('exibe selo neutro "até DD/MM", caption do dia e delta vs dia anterior', () => {
    renderColumn({
      ...baseStore,
      nome: 'Momma Asa Sul',
      channel: 'linx-lagged',
      deltaOntem: -8,
      vendas: {
        valor: 4200,
        cupons: null,
        ticketMedio: null,
        dataReferencia: '2026-06-03', // qua 03/06
        isLive: false,
        caixaAberto: null,
        atualizadoEm: null,
      },
    });
    expect(screen.getByTestId('tv-source-chip-lagged')).toHaveTextContent('até 03/06');
    expect(screen.queryByText('ao vivo')).not.toBeInTheDocument();
    expect(screen.getByText(/último dia com dados/)).toBeInTheDocument();
    expect(screen.getByTestId('tv-delta-chip')).toHaveTextContent('8% vs dia ant.');
  });
});

import { fireEvent, render, screen } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { TvHero } from './TvHero';
import type { TvFreshness, TvNetworkSummary } from '../model/types';

// qui 04/06/2026, 14:30 — dentro da janela comercial
const NOW = new Date(2026, 5, 4, 14, 30);

const network: TvNetworkSummary = {
  vendasHoje: 21_300,
  metaDia: 30_000,
  pctMetaProRata: 110,
  deltaSemana: 5,
  deltaOntem: 12,
  perdas: { valor: 480, itens: 7, deltaPct: 25 },
  compras: { valor: 5_200, deltaPct: -10 },
  alertasCriticos: 2,
  lojasLive: 3,
  lojasDefasadas: 2,
};

const freshness: TvFreshness = {
  vendasLive: {
    updatedAt: new Date(2026, 5, 4, 14, 29).toISOString(),
    level: 'fresh',
    expectedIntervalMs: 60_000,
  },
  estoque: {
    updatedAt: new Date(2026, 5, 4, 14, 25).toISOString(),
    level: 'fresh',
    expectedIntervalMs: 300_000,
  },
  geradoEm: NOW.toISOString(),
};

function renderHero(period: 'today' | 'week' | 'month' = 'today') {
  const onPeriodChange = vi.fn();
  render(
    <TvHero
      network={network}
      freshness={freshness}
      now={NOW}
      period={period}
      onPeriodChange={onPeriodChange}
    />,
  );
  return { onPeriodChange };
}

describe('TvHero v3 — métricas da rede', () => {
  it('mostra vendas de hoje + delta principal vs ONTEM', () => {
    renderHero();
    expect(screen.getByTestId('tv-hero-sales')).toHaveTextContent('R$ 21,3k');
    expect(screen.getByTestId('tv-delta-chip')).toHaveTextContent('12% vs ontem');
  });

  it('mostra compras e perdas do período com rótulo do filtro', () => {
    renderHero();
    expect(screen.getByText('COMPRAS · hoje')).toBeInTheDocument();
    expect(screen.getByTestId('tv-hero-compras')).toHaveTextContent('R$ 5,2k');
    expect(screen.getByText('PERDAS · hoje')).toBeInTheDocument();
    expect(screen.getByTestId('tv-hero-perdas')).toHaveTextContent('R$ 480');
    expect(screen.getByTestId('tv-hero-perdas')).toHaveTextContent('7 itens');
  });

  it('rótulo das métricas acompanha o período selecionado', () => {
    renderHero('month');
    expect(screen.getByText('COMPRAS · mês')).toBeInTheDocument();
    expect(screen.getByText('PERDAS · mês')).toBeInTheDocument();
  });

  it('alertas críticos em vermelho com contagem', () => {
    renderHero();
    expect(screen.getByTestId('tv-hero-alerts')).toHaveTextContent('2');
  });

  it('barra de meta segue presente como secundária', () => {
    renderHero();
    expect(screen.getByTestId('tv-meta-bar')).toBeInTheDocument();
    expect(screen.getByText(/71% da meta/)).toBeInTheDocument();
  });
});

describe('TvHero v3 — filtro global Hoje/Semana/Mês', () => {
  it('dispara onPeriodChange ao clicar em outro período', () => {
    const { onPeriodChange } = renderHero();
    fireEvent.click(screen.getByRole('button', { name: 'Semana' }));
    expect(onPeriodChange).toHaveBeenCalledWith('week');
    fireEvent.click(screen.getByRole('button', { name: 'Mês' }));
    expect(onPeriodChange).toHaveBeenCalledWith('month');
  });

  it('marca o período ativo com aria-pressed', () => {
    renderHero('week');
    expect(screen.getByRole('button', { name: 'Semana' })).toHaveAttribute(
      'aria-pressed',
      'true',
    );
    expect(screen.getByRole('button', { name: 'Hoje' })).toHaveAttribute(
      'aria-pressed',
      'false',
    );
