import { fireEvent, render, screen } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import type { TvDateRange } from '../model/types';
import type { TvStoreDetailData } from '../model/useTvStoreDetail';
import { periodRange, toIsoDateLocal } from '../model/tvMath';
import TvStoreDetailPage from './TvStoreDetail.page';

const useTvStoreDetailMock = vi.hoisted(() => vi.fn());

vi.mock('../model/useTvStoreDetail', () => ({
  useTvStoreDetail: useTvStoreDetailMock,
}));

vi.mock('../model/useTvRealtime', () => ({ useTvRealtime: vi.fn() }));

function detailData(
  lojaId: number | null,
  range: TvDateRange,
  overrides: Partial<TvStoreDetailData> = {},
): TvStoreDetailData {
  return {
    lojaId,
    nome: lojaId != null ? 'Momma Águas Claras' : null,
    channel: 'degust-live',
    range,
    previousRange: range,
    vendas: { valor: 8400, deltaPct: 12 },
    perdas: { valor: 120, itens: 3, deltaPct: -10 },
    compras: { valor: 2600, deltaPct: null },
    movimentos: { entradas: 14, saidas: 9, total: 23, deltaPct: 5 },
    perdasList: [],
    notasList: [],
    criticalItems: [],
    feed: [],
    isLoading: false,
    isError: false,
    ...overrides,
  };
}

beforeEach(() => {
  useTvStoreDetailMock.mockReset();
  useTvStoreDetailMock.mockImplementation((lojaId: number | null, range: TvDateRange) =>
    detailData(lojaId, range),
  );
});

function renderPage(path = '/tv/loja/5') {
  return render(
    <MemoryRouter initialEntries={[path]}>
      <Routes>
        <Route path="/tv/loja/:id" element={<TvStoreDetailPage />} />
        <Route path="/tv" element={<div>torre-de-controle</div>} />
      </Routes>
    </MemoryRouter>,
  );
}

describe('TvStoreDetailPage — KPIs', () => {
  it('renderiza os 4 KPIs com valores e deltas vs período anterior', () => {
    renderPage();
    expect(screen.getByText('Momma Águas Claras')).toBeInTheDocument();
    expect(screen.getByTestId('tv-detail-kpi-vendas')).toHaveTextContent('R$ 8,4k');
    expect(screen.getByTestId('tv-detail-kpi-vendas')).toHaveTextContent('12% vs anterior');
    expect(screen.getByTestId('tv-detail-kpi-perdas')).toHaveTextContent('R$ 120');
    expect(screen.getByTestId('tv-detail-kpi-perdas')).toHaveTextContent('3 itens');
    expect(screen.getByTestId('tv-detail-kpi-compras')).toHaveTextContent('R$ 2,6k');
    expect(screen.getByTestId('tv-detail-kpi-compras')).toHaveTextContent(
      'sem base anterior',
    );
    expect(screen.getByTestId('tv-detail-kpi-movimentos')).toHaveTextContent('23');
  });

  it('fábrica não tem KPI de vendas (nunca "R$ 0" falso)', () => {
    useTvStoreDetailMock.mockImplementation((lojaId: number | null, range: TvDateRange) =>
      detailData(lojaId, range, { channel: 'factory', nome: 'Fábrica' }),
    );
    renderPage('/tv/loja/1');
    expect(screen.queryByTestId('tv-detail-kpi-vendas')).not.toBeInTheDocument();
    expect(screen.getByTestId('tv-detail-kpi-perdas')).toBeInTheDocument();
  });
});

describe('TvStoreDetailPage — filtro de data próprio', () => {
  it('inicia em Hoje (from = to = hoje) e muda o range ao clicar em Mês', () => {
    renderPage();
    const today = toIsoDateLocal(new Date());
    expect(useTvStoreDetailMock).toHaveBeenLastCalledWith(5, {
      from: today,
      to: today,
    });

    fireEvent.click(screen.getByRole('button', { name: 'Mês' }));
    expect(useTvStoreDetailMock).toHaveBeenLastCalledWith(
      5,
      periodRange('month', new Date()),
    );
  });

  it('preset 7 dias cobre os últimos 7 dias fechados em hoje', () => {
    renderPage();
    fireEvent.click(screen.getByRole('button', { name: '7 dias' }));
    const lastCall = useTvStoreDetailMock.mock.calls.at(-1) as [number, TvDateRange];
    const today = toIsoDateLocal(new Date());
    expect(lastCall[0]).toBe(5);
    expect(lastCall[1].to).toBe(today);
    expect(lastCall[1].from < lastCall[1].to).toBe(true);
  });
});

describe('TvStoreDetailPage — estados vazios explícitos', () => {
  it('todas as listas vazias confirmam explicitamente', () => {
    renderPage();
    expect(screen.getByTestId('tv-detail-perdas-empty')).toHaveTextContent(
      'Nenhuma perda registrada no período',
    );
    expect(screen.getByTestId('tv-detail-notas-empty')).toHaveTextContent(
      'Nenhuma nota fiscal de compra no período',
    );
    expect(screen.getByTestId('tv-detail-critical-empty')).toHaveTextContent(
      'Estoque ok — nenhum item crítico',
    );
    expect(screen.getByTestId('tv-detail-feed-empty')).toHaveTextContent(
      'Sem movimentações no período',
    );
  });

  it('listas populadas renderizam linhas com os dados', () => {
    useTvStoreDetailMock.mockImplementation((lojaId: number | null, range: TvDateRange) =>
      detailData(lojaId, range, {
        perdasList: [
          {
            id: 1,
            produtoNome: 'Brownie',
            quantidade: 4,
            unidade: 'un',
            motivo: 'vencido',
            valor: 48,
            data: new Date(2026, 5, 4, 9, 12).toISOString(),
          },
        ],
        notasList: [
          {
            id: 9,
            numero: '12345',
            fornecedor: 'Fornecedor X',
            valor: 950.5,
            dataNota: '2026-06-03',
          },
        ],
        criticalItems: [
          { nome: 'Cookie', quantidade: 0, minima: 5, severity: 'zerado' },
        ],
        feed: [
          {
            hora: '14:21',
            timestamp: new Date(2026, 5, 4, 14, 21).toISOString(),
            tipo: 'entrada',
            produtoNome: 'Naked',
            quantidade: 6,
          },
        ],
      }),
    );
    renderPage();
    expect(screen.getByTestId('tv-detail-perda-row')).toHaveTextContent('Brownie');
    expect(screen.getByTestId('tv-detail-perda-row')).toHaveTextContent('vencido');
    expect(screen.getByTestId('tv-detail-nota-row')).toHaveTextContent('Fornecedor X');
    expect(screen.getByTestId('tv-detail-nota-row')).toHaveTextContent('NF 12345');
    expect(screen.getByTestId('tv-detail-critical-row')).toHaveTextContent('Cookie');
    expect(screen.getByTestId('tv-detail-critical-row')).toHaveTextContent('0 un');
    expect(screen.getByTestId('tv-detail-feed-row')).toHaveTextContent('6× Naked');
  });
});

describe('TvStoreDetailPage — rotas inválidas e voltar', () => {
  it('id não numérico mostra "Loja não encontrada"', () => {
    renderPage('/tv/loja/abc');
    expect(screen.getByText('Loja não encontrada')).toBeInTheDocument();
  });

  it('botão voltar navega para /tv', () => {
    renderPage();
    fireEvent.click(
      screen.getByRole('button', { name: 'Voltar para a Torre de Controle' }),
    );
    expect(screen.getByText('torre-de-controle')).toBeInTheDocument();
  });
});

